impl IndexBuilder {
    fn collect_public_surface_file(
        &mut self,
        file: &Path,
        syntax: &File,
        context: IndexModuleContext<'_>,
        visited: &mut BTreeSet<PathBuf>,
    ) -> Result<()> {
        if !attributes_are_enabled(&syntax.attrs, &self.coordinate) {
            return Ok(());
        }
        let canonical = fs::canonicalize(file).map_err(|source| Error::io(file, source))?;
        if !visited.insert(canonical) {
            return Ok(());
        }
        self.collect_public_surface_items(file, &syntax.items, context, visited)
    }

    fn collect_public_surface_items(
        &mut self,
        file: &Path,
        items: &[Item],
        context: IndexModuleContext<'_>,
        visited: &mut BTreeSet<PathBuf>,
    ) -> Result<()> {
        let modules = context.modules;
        let modules_public = context.modules_public;
        for item in items {
            if !item_is_enabled(item, &self.coordinate)
                || !item_attributes_are_indexable(item_attributes(item), &self.coordinate)
            {
                continue;
            }
            match item {
                Item::Mod(module) => {
                    self.local_modules
                        .entry(module_key(modules))
                        .or_default()
                        .insert(module.ident.to_string());
                    let mut child_modules = modules.to_vec();
                    child_modules.push(module.ident.to_string());
                    let child_public = modules_public && is_public(&module.vis);
                    if let Some((_, items)) = &module.content {
                        let child_module_dir =
                            context.regular_module_dir.join(module.ident.to_string());
                        self.collect_public_surface_items(
                            file,
                            items,
                            IndexModuleContext {
                                modules: &child_modules,
                                modules_public: child_public,
                                regular_module_dir: &child_module_dir,
                                path_attribute_dir: &child_module_dir,
                            },
                            visited,
                        )?;
                    } else {
                        let resolved = resolve_module_file(
                            context.regular_module_dir,
                            context.path_attribute_dir,
                            file,
                            module,
                        )?;
                        let source = fs::read_to_string(&resolved.file)
                            .map_err(|source| Error::io(&resolved.file, source))?;
                        let syntax = syn::parse_file(&source).map_err(|error| {
                            Error::message(format!(
                                "{}: invalid Rust syntax: {error}",
                                resolved.file.display()
                            ))
                        })?;
                        self.collect_public_surface_file(
                            &resolved.file,
                            &syntax,
                            IndexModuleContext {
                                modules: &child_modules,
                                modules_public: child_public,
                                regular_module_dir: &resolved.regular_module_dir,
                                path_attribute_dir: &resolved.path_attribute_dir,
                            },
                            visited,
                        )?;
                    }
                }
                Item::Use(item) => {
                    self.collect_imports(modules, item);
                    if !is_public(&item.vis) {
                        continue;
                    }
                    let module = module_key(modules);
                    let mut entries = Vec::new();
                    flatten_use_tree(&item.tree, &mut Vec::new(), &mut entries);
                    for (alias, raw_path) in entries {
                        let alias = item_key(modules, &alias);
                        self.public_alias_targets
                            .entry(alias.clone())
                            .or_default()
                            .extend(normalize_import_paths(&module, &raw_path));
                        if modules_public {
                            self.public_alias_entries.insert(alias);
                        }
                    }
                }
                Item::Fn(item) => {
                    let name = item.sig.ident.to_string();
                    self.declared_value_paths.insert(item_key(modules, &name));
                    if is_public(&item.vis) {
                        self.record_public_declaration(modules, modules_public, &name);
                    }
                }
                Item::Struct(item) => {
                    self.collect_type(modules, &item.ident.to_string());
                    self.record_field_types(modules, &item.ident.to_string(), item.fields.iter());
                    self.record_derived_traits(modules, &item.ident.to_string(), &item.attrs);
                    self.record_repr_c(modules, &item.ident.to_string(), &item.attrs);
                    self.record_raw_storage(modules, &item.ident.to_string(), item.fields.iter());
                    if is_public(&item.vis) {
                        self.record_public_fields(
                            modules,
                            &item.ident.to_string(),
                            item.fields.iter(),
                        );
                        self.record_public_type_declaration(
                            modules,
                            modules_public,
                            &item.ident.to_string(),
                        );
                    }
                }
                Item::Enum(item) => {
                    self.collect_type(modules, &item.ident.to_string());
                    if is_public(&item.vis) {
                        self.record_public_type_declaration(
                            modules,
                            modules_public,
                            &item.ident.to_string(),
                        );
                    }
                }
                Item::Type(item) => {
                    self.collect_type(modules, &item.ident.to_string());
                    self.collect_return_wrapper_alias(modules, item);
                    if is_public(&item.vis) {
                        self.record_public_type_declaration(
                            modules,
                            modules_public,
                            &item.ident.to_string(),
                        );
                    }
                }
                Item::Union(item) => {
                    self.collect_type(modules, &item.ident.to_string());
                    self.record_field_types(
                        modules,
                        &item.ident.to_string(),
                        item.fields.named.iter(),
                    );
                    self.record_raw_storage(
                        modules,
                        &item.ident.to_string(),
                        item.fields.named.iter(),
                    );
                    if is_public(&item.vis) {
                        self.record_public_fields(
                            modules,
                            &item.ident.to_string(),
                            item.fields.named.iter(),
                        );
                        self.record_public_type_declaration(
                            modules,
                            modules_public,
                            &item.ident.to_string(),
                        );
                    }
                }
                Item::Trait(item) => {
                    let name = item.ident.to_string();
                    self.collect_type(modules, &name);
                    self.declared_traits.insert(item_key(modules, &name));
                    if is_public(&item.vis) {
                        self.record_public_declaration(modules, modules_public, &name);
                    }
                }
                Item::Const(item) => {
                    let name = item.ident.to_string();
                    self.declared_value_paths.insert(item_key(modules, &name));
                    if is_public(&item.vis) {
                        self.record_public_declaration(modules, modules_public, &name);
                    }
                }
                Item::Static(item) => {
                    let name = item.ident.to_string();
                    self.declared_value_paths.insert(item_key(modules, &name));
                    self.record_static_type(modules, &name, item.ty.as_ref());
                    self.collect_static_callable_array(modules, item);
                    if is_public(&item.vis) {
                        self.record_public_declaration(modules, modules_public, &name);
                    }
                }
                _ => {}
            }
        }
        Ok(())
    }

    fn record_public_declaration(&mut self, modules: &[String], modules_public: bool, name: &str) {
        let declaration = item_key(modules, name);
        self.public_declarations.insert(declaration.clone());
        if modules_public {
            self.public_alias_entries.insert(declaration);
        }
    }

    fn record_public_type_declaration(
        &mut self,
        modules: &[String],
        modules_public: bool,
        name: &str,
    ) {
        self.public_type_declarations
            .insert(item_key(modules, name));
        self.record_public_declaration(modules, modules_public, name);
    }

    fn record_public_fields<'a>(
        &mut self,
        modules: &[String],
        owner: &str,
        fields: impl IntoIterator<Item = &'a syn::Field>,
    ) {
        let owner = item_key(modules, owner);
        for field in fields {
            let Some(name) = &field.ident else {
                continue;
            };
            if is_public(&field.vis) && attributes_are_enabled(&field.attrs, &self.coordinate) {
                self.public_fields_by_owner
                    .entry(owner.clone())
                    .or_default()
                    .insert(name.to_string());
            }
        }
    }

    fn record_field_types<'a>(
        &mut self,
        modules: &[String],
        owner: &str,
        fields: impl IntoIterator<Item = &'a syn::Field>,
    ) {
        let module = module_key(modules);
        let owner = item_key(modules, owner);
        for (index, field) in fields.into_iter().enumerate() {
            if !attributes_are_enabled(&field.attrs, &self.coordinate) {
                continue;
            }
            let field_name = field
                .ident
                .as_ref()
                .map_or_else(|| index.to_string(), ToString::to_string);
            self.field_order_by_owner
                .entry(owner.clone())
                .or_default()
                .push(field_name.clone());
            self.field_syntax_by_owner
                .entry(owner.clone())
                .or_default()
                .insert(
                    field_name.clone(),
                    FieldTypeSyntax {
                        module: module.clone(),
                        ty: field.ty.clone(),
                    },
                );
            let Some(segments) = direct_value_type_path(&field.ty) else {
                continue;
            };
            self.field_types_by_owner
                .entry(owner.clone())
                .or_default()
                .insert(
                    field_name,
                    TypeRef {
                        module: module.clone(),
                        segments,
                    },
                );
        }
    }

    fn record_derived_traits(&mut self, modules: &[String], owner: &str, attributes: &[Attribute]) {
        let traits = attributes
            .iter()
            .filter(|attribute| attribute.path().is_ident("derive"))
            .filter_map(|attribute| {
                let parser =
                    syn::punctuated::Punctuated::<syn::Path, syn::Token![,]>::parse_terminated;
                attribute.parse_args_with(parser).ok()
            })
            .flat_map(|traits| traits.into_iter())
            .filter_map(|path| {
                (path.leading_colon.is_none()
                    && path.segments.len() == 1
                    && matches!(path.segments[0].arguments, syn::PathArguments::None))
                .then(|| path.segments[0].ident.to_string())
            })
            .collect::<BTreeSet<_>>();
        self.derived_traits_by_owner
            .insert(item_key(modules, owner), traits);
    }

    fn record_repr_c(&mut self, modules: &[String], owner: &str, attributes: &[Attribute]) {
        let repr_attributes = attributes
            .iter()
            .filter(|attribute| attribute.path().is_ident("repr"))
            .collect::<Vec<_>>();
        let cfg_attr_changes_repr = attributes.iter().any(|attribute| {
            if !attribute.path().is_ident("cfg_attr") {
                return false;
            }
            let parser = syn::punctuated::Punctuated::<Meta, syn::Token![,]>::parse_terminated;
            attribute.parse_args_with(parser).map_or(true, |metas| {
                metas
                    .iter()
                    .skip(1)
                    .any(|meta| meta.path().is_ident("repr"))
            })
        });
        let exact_repr_c = match repr_attributes.as_slice() {
            [attribute] => {
                let parser = syn::punctuated::Punctuated::<Meta, syn::Token![,]>::parse_terminated;
                attribute.parse_args_with(parser).is_ok_and(|metas| {
                    metas.len() == 1
                        && matches!(metas.first(), Some(Meta::Path(path)) if path.is_ident("C"))
                })
            }
            _ => false,
        };
        if exact_repr_c && !cfg_attr_changes_repr {
            self.repr_c_types.insert(item_key(modules, owner));
        }
    }

    fn record_static_type(&mut self, modules: &[String], name: &str, ty: &Type) {
        self.static_type_syntax_by_path.insert(
            item_key(modules, name),
            FieldTypeSyntax {
                module: module_key(modules),
                ty: ty.clone(),
            },
        );
    }

    fn record_raw_storage<'a>(
        &mut self,
        modules: &[String],
        owner: &str,
        fields: impl IntoIterator<Item = &'a syn::Field>,
    ) {
        let module = module_key(modules);
        let owner = item_key(modules, owner);
        for (index, field) in fields.into_iter().enumerate() {
            if !attributes_are_enabled(&field.attrs, &self.coordinate) {
                continue;
            }
            let Some(segments) = direct_value_type_path(&field.ty) else {
                continue;
            };
            self.raw_storage_by_owner
                .entry(owner.clone())
                .or_default()
                .insert(RawStorageRef {
                    raw_type: TypeRef {
                        module: module.clone(),
                        segments,
                    },
                    member_chain: vec![
                        field
                            .ident
                            .as_ref()
                            .map_or_else(|| index.to_string(), ToString::to_string),
                    ],
                });
        }
    }

    fn collect_static_callable_array(&mut self, modules: &[String], item: &syn::ItemStatic) {
        if !matches!(item.mutability, syn::StaticMutability::None) {
            return;
        }
        let Expr::Array(array) = strip_expression_wrappers(&item.expr) else {
            return;
        };
        if array.elems.is_empty()
            || array.elems.iter().any(|element| {
                nested_attributes_decision(expression_attributes(element), &self.coordinate)
                    != CfgDecision::Enabled
            })
        {
            return;
        }
        let elements = array
            .elems
            .iter()
            .map(|element| {
                let Expr::Path(path) = strip_expression_wrappers(element) else {
                    return None;
                };
                (path.qself.is_none()).then(|| CallTarget::Path {
                    segments: path_segments(&path.path),
                    qself: None,
                })
            })
            .collect::<Option<Vec<_>>>();
        let Some(elements) = elements else {
            return;
        };
        self.static_callable_arrays
            .entry(item_key(modules, &item.ident.to_string()))
            .or_default()
            .push(StaticCallableArrayDefinition {
                module: module_key(modules),
                elements,
            });
    }

    fn expanded_raw_storage(&self, owner: &str) -> Vec<RawStorageRef> {
        self.expand_raw_storage(owner, &mut BTreeSet::new())
            .map(|storage| storage.into_iter().collect())
            .unwrap_or_default()
    }

    fn expand_raw_storage(
        &self,
        owner: &str,
        visiting: &mut BTreeSet<String>,
    ) -> Option<BTreeSet<RawStorageRef>> {
        if !visiting.insert(owner.to_owned()) {
            return None;
        }
        let expanded = (|| {
            let mut expanded = BTreeSet::new();
            for storage in self.raw_storage_by_owner.get(owner).into_iter().flatten() {
                if self.resolve_ffi_type_ref(&storage.raw_type).is_some() {
                    expanded.insert(storage.clone());
                    continue;
                }

                let candidates = self
                    .path_candidates(&storage.raw_type.module, &storage.raw_type.segments)
                    .into_iter()
                    .filter(|candidate| self.is_declared_type(candidate))
                    .collect::<BTreeSet<_>>();
                if candidates.is_empty() {
                    continue;
                }
                if candidates.len() != 1 {
                    return None;
                }
                let nested_owner = candidates.first().expect("one nested storage owner");
                let nested = self.expand_raw_storage(nested_owner, visiting)?;
                for nested_storage in nested {
                    expanded.insert(RawStorageRef {
                        raw_type: nested_storage.raw_type,
                        member_chain: storage
                            .member_chain
                            .iter()
                            .cloned()
                            .chain(nested_storage.member_chain)
                            .collect(),
                    });
                }
            }
            Some(expanded)
        })();
        visiting.remove(owner);
        expanded
    }

    fn resolve_public_surface(&mut self, crate_name: &str) {
        let entries = self.public_alias_entries.clone();
        let mut aliases_by_declaration: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
        let mut resolved_aliases = Vec::new();
        for alias in entries {
            let PublicAliasResolution::Unique(declaration) =
                self.resolve_public_alias(&alias, &mut BTreeSet::new())
            else {
                continue;
            };
            let public_path = format!("{crate_name}::{alias}");
            self.public_paths.insert(public_path.clone());
            resolved_aliases.push((public_path.clone(), declaration.clone()));
            aliases_by_declaration
                .entry(declaration)
                .or_default()
                .insert(public_path);
        }
        self.canonical_public_paths = aliases_by_declaration
            .into_iter()
            .filter_map(|(declaration, aliases)| {
                aliases
                    .into_iter()
                    .min_by_key(|alias| (alias.matches("::").count(), alias.clone()))
                    .map(|alias| (declaration, alias))
            })
            .collect();
        self.public_alias_paths = resolved_aliases
            .into_iter()
            .filter_map(|(alias, declaration)| {
                self.canonical_public_paths
                    .get(&declaration)
                    .cloned()
                    .map(|canonical| (alias, canonical))
            })
            .collect();
        self.public_field_paths = self
            .public_fields_by_owner
            .iter()
            .filter_map(|(owner, fields)| {
                self.canonical_public_paths
                    .get(owner)
                    .map(|owner| (owner, fields))
            })
            .flat_map(|(owner, fields)| fields.iter().map(move |field| format!("{owner}::{field}")))
            .collect();
        self.public_paths
            .extend(self.public_field_paths.iter().cloned());
    }

    fn resolve_public_alias(
        &self,
        alias: &str,
        visiting: &mut BTreeSet<String>,
    ) -> PublicAliasResolution {
        if self.public_declarations.contains(alias) {
            return PublicAliasResolution::Unique(alias.to_owned());
        }
        let Some(targets) = self.public_alias_targets.get(alias) else {
            return PublicAliasResolution::Missing;
        };
        if !visiting.insert(alias.to_owned()) {
            return PublicAliasResolution::Invalid;
        }
        let mut declarations = BTreeSet::new();
        for target in targets {
            match self.resolve_public_alias(target, visiting) {
                PublicAliasResolution::Missing => {}
                PublicAliasResolution::Unique(declaration) => {
                    declarations.insert(declaration);
                }
                PublicAliasResolution::Invalid => {
                    visiting.remove(alias);
                    return PublicAliasResolution::Invalid;
                }
            }
        }
        visiting.remove(alias);
        match declarations.len() {
            0 => PublicAliasResolution::Missing,
            1 => PublicAliasResolution::Unique(
                declarations.into_iter().next().expect("one declaration"),
            ),
            _ => PublicAliasResolution::Invalid,
        }
    }

    fn public_type_path(&self, _crate_name: &str, item: &str) -> Option<String> {
        self.canonical_public_paths.get(item).cloned()
    }

    fn collect_file(
        &mut self,
        file: &Path,
        syntax: &File,
        context: IndexModuleContext<'_>,
    ) -> Result<()> {
        if !attributes_are_enabled(&syntax.attrs, &self.coordinate) {
            return Ok(());
        }
        let canonical = fs::canonicalize(file).map_err(|source| Error::io(file, source))?;
        if !self.visited_files.insert(canonical) {
            return Ok(());
        }
        self.collect_items(file, &syntax.items, context)
    }

    fn collect_items(
        &mut self,
        file: &Path,
        items: &[Item],
        context: IndexModuleContext<'_>,
    ) -> Result<()> {
        let crate_name = self.crate_name.clone();
        let modules = context.modules;
        let modules_public = context.modules_public;
        for item in items {
            if !item_is_enabled(item, &self.coordinate)
                || !item_attributes_are_indexable(item_attributes(item), &self.coordinate)
            {
                continue;
            }
            match item {
                Item::Mod(module) => {
                    self.local_modules
                        .entry(module_key(modules))
                        .or_default()
                        .insert(module.ident.to_string());
                    self.collect_module(file, module, context)?
                }
                Item::Fn(function) => {
                    let name = function.sig.ident.to_string();
                    let public_path = is_public(&function.vis)
                        .then(|| {
                            self.canonical_public_paths
                                .get(&item_key(modules, &name))
                                .cloned()
                        })
                        .flatten();
                    if let Some(path) = &public_path {
                        self.public_paths.insert(path.clone());
                        self.public_callable_paths.insert(path.clone());
                        if function.sig.unsafety.is_none() {
                            self.public_safe_callable_paths.insert(path.clone());
                        }
                    }
                    let node = node_from_body(
                        NodeIdentity {
                            module: module_key(modules),
                            owner: None,
                            generic_type_parameters: generic_type_parameters([&function
                                .sig
                                .generics]),
                            is_drop: false,
                            callable_kind: Some(CallableEvidenceKind::Free),
                            ident: name,
                            public_path,
                        },
                        &function.sig,
                        &function.block,
                        &[],
                        self,
                    );
                    self.nodes.push(node);
                }
                Item::Impl(item_impl) => self.collect_impl(item_impl, &crate_name, modules),
                Item::Struct(item) => {
                    self.collect_type(modules, &item.ident.to_string());
                    self.collect_raii_fields(&crate_name, modules, item);
                }
                Item::Enum(item) => self.collect_type(modules, &item.ident.to_string()),
                Item::Type(item) => self.collect_type(modules, &item.ident.to_string()),
                Item::Trait(item) => {
                    let name = item.ident.to_string();
                    self.collect_type(modules, &name);
                    let owner = self.public_type_path(&crate_name, &item_key(modules, &name));
                    let trait_public = owner.is_some();
                    let owner = owner.unwrap_or_else(|| path_with(&crate_name, modules, &name));
                    for trait_item in &item.items {
                        if let syn::TraitItem::Fn(method) = trait_item {
                            if !attributes_are_enabled(&method.attrs, &self.coordinate)
                                || !item_attributes_are_indexable(&method.attrs, &self.coordinate)
                            {
                                continue;
                            }
                            let public_path = trait_public.then(|| {
                                let path = format!("{owner}::{}", method.sig.ident);
                                self.public_paths.insert(path.clone());
                                self.public_callable_paths.insert(path.clone());
                                if method.sig.unsafety.is_none() {
                                    self.public_safe_callable_paths.insert(path.clone());
                                }
                                path
                            });
                            if let Some(block) = &method.default {
                                let node = node_from_body(
                                    NodeIdentity {
                                        module: module_key(modules),
                                        owner: Some(TypeRef {
                                            module: module_key(modules),
                                            segments: vec![name.clone()],
                                        }),
                                        generic_type_parameters: generic_type_parameters([
                                            &item.generics,
                                            &method.sig.generics,
                                        ]),
                                        is_drop: false,
                                        callable_kind: None,
                                        ident: method.sig.ident.to_string(),
                                        public_path,
                                    },
                                    &method.sig,
                                    block,
                                    &[],
                                    self,
                                );
                                self.nodes.push(node);
                            }
                        }
                    }
                }
                Item::Const(item) if modules_public && is_public(&item.vis) => {
                    self.public_paths.insert(path_with(
                        &crate_name,
                        modules,
                        &item.ident.to_string(),
                    ));
                }
                Item::Static(item) if modules_public && is_public(&item.vis) => {
                    self.public_paths.insert(path_with(
                        &crate_name,
                        modules,
                        &item.ident.to_string(),
                    ));
                }
                Item::Use(item) => {
                    self.collect_imports(modules, item);
                }
                Item::ExternCrate(item) => self.collect_extern_crate(modules, item),
                _ => {}
            }
        }
        Ok(())
    }

    fn collect_module(
        &mut self,
        file: &Path,
        module: &ItemMod,
        context: IndexModuleContext<'_>,
    ) -> Result<()> {
        let modules = context.modules;
        let mut child_modules = modules.to_vec();
        child_modules.push(module.ident.to_string());
        let child_public = context.modules_public && is_public(&module.vis);
        if child_public {
            self.public_paths
                .insert(format!("{}::{}", self.crate_name, child_modules.join("::")));
        }
        if let Some((_, items)) = &module.content {
            let child_module_dir = context.regular_module_dir.join(module.ident.to_string());
            return self.collect_items(
                file,
                items,
                IndexModuleContext {
                    modules: &child_modules,
                    modules_public: child_public,
                    regular_module_dir: &child_module_dir,
                    path_attribute_dir: &child_module_dir,
                },
            );
        }
        let resolved = resolve_module_file(
            context.regular_module_dir,
            context.path_attribute_dir,
            file,
            module,
        )?;
        let source = fs::read_to_string(&resolved.file)
            .map_err(|source| Error::io(&resolved.file, source))?;
        let syntax = syn::parse_file(&source).map_err(|error| {
            Error::message(format!(
                "{}: invalid Rust syntax: {error}",
                resolved.file.display()
            ))
        })?;
        self.collect_file(
            &resolved.file,
            &syntax,
            IndexModuleContext {
                modules: &child_modules,
                modules_public: child_public,
                regular_module_dir: &resolved.regular_module_dir,
                path_attribute_dir: &resolved.path_attribute_dir,
            },
        )
    }

    fn resolve_trait_identity(
        &self,
        trait_path: &syn::Path,
        modules: &[String],
    ) -> Option<ProvenTrait> {
        let module = module_key(modules);
        let segments = path_segments(trait_path);
        let candidates = self.path_candidates(&module, &segments);
        let local_traits = candidates
            .iter()
            .filter(|candidate| self.declared_traits.contains(*candidate))
            .collect::<BTreeSet<_>>();
        if !local_traits.is_empty() {
            return (local_traits.len() == 1
                && self
                    .canonical_public_paths
                    .contains_key(*local_traits.first().expect("one local trait")))
            .then_some(ProvenTrait::Public);
        }

        let proven = candidates
            .iter()
            .filter_map(|candidate| standard_trait_identity(candidate))
            .collect::<BTreeSet<_>>();
        if proven.len() == 1 {
            return proven.first().copied();
        }
        if !proven.is_empty() || segments.len() != 1 {
            return None;
        }

        let name = segments.first()?;
        let explicitly_bound = self
            .imports
            .get(&module)
            .is_some_and(|imports| imports.contains_key(name));
        if explicitly_bound {
            return None;
        }
        prelude_trait_identity(name)
    }

    fn collect_impl(&mut self, item_impl: &ItemImpl, crate_name: &str, modules: &[String]) {
        let Some(owner_name) = type_name(&item_impl.self_ty) else {
            return;
        };
        let owner_reference = TypeRef {
            module: module_key(modules),
            segments: type_path_segments(&item_impl.self_ty)
                .unwrap_or_else(|| vec![owner_name.clone()]),
        };
        let resolved_owner = self.resolve_type_ref(&owner_reference);
        let owner_path = resolved_owner
            .as_ref()
            .and_then(|item| self.public_type_path(crate_name, item));
        let owner = owner_path
            .clone()
            .unwrap_or_else(|| path_with(crate_name, modules, &owner_name));
        let trait_path = item_impl.trait_.as_ref().map(|(_, path, _)| path);
        let owner_public = owner_path.is_some();
        let trait_identity = trait_path.and_then(|path| self.resolve_trait_identity(path, modules));
        let public_trait = owner_public && trait_identity.is_some();
        let is_drop = trait_identity == Some(ProvenTrait::Drop);
        let raw_storage = resolved_owner
            .as_deref()
            .map(|owner| self.expanded_raw_storage(owner))
            .unwrap_or_default();
        for item in &item_impl.items {
            let ImplItem::Fn(method) = item else {
                continue;
            };
            if !attributes_are_enabled(&method.attrs, &self.coordinate)
                || !item_attributes_are_indexable(&method.attrs, &self.coordinate)
            {
                continue;
            }
            let is_reachable = owner_public
                && ((is_public(&method.vis) && item_impl.trait_.is_none()) || public_trait);
            let public_path = is_reachable.then(|| {
                if is_drop {
                    owner.clone()
                } else {
                    format!("{owner}::{}", method.sig.ident)
                }
            });
            if let Some(path) = &public_path {
                self.public_paths.insert(path.clone());
                if !is_drop {
                    self.public_callable_paths.insert(path.clone());
                    if method.sig.unsafety.is_none() {
                        self.public_safe_callable_paths.insert(path.clone());
                    }
                }
            }
            let node = node_from_body(
                NodeIdentity {
                    module: module_key(modules),
                    owner: Some(owner_reference.clone()),
                    generic_type_parameters: generic_type_parameters([
                        &item_impl.generics,
                        &method.sig.generics,
                    ]),
                    is_drop,
                    callable_kind: (item_impl.trait_.is_none() && !is_drop)
                        .then_some(CallableEvidenceKind::Inherent),
                    ident: method.sig.ident.to_string(),
                    public_path,
                },
                &method.sig,
                &method.block,
                &raw_storage,
                self,
            );
            self.nodes.push(node);
        }
    }

    fn collect_type(&mut self, modules: &[String], name: &str) {
        let path = item_key(modules, name);
        self.declared_types
            .entry(name.to_owned())
            .or_default()
            .insert(path.clone());
        self.declared_type_paths.insert(path);
    }

    fn collect_return_wrapper_alias(&mut self, modules: &[String], item: &syn::ItemType) {
        let mut parameters = item.generics.params.iter();
        let value_parameter = match (parameters.next(), parameters.next()) {
            (Some(syn::GenericParam::Type(parameter)), None)
                if parameter.bounds.is_empty()
                    && parameter.default.is_none()
                    && item.generics.where_clause.is_none() =>
            {
                Some(parameter.ident.to_string())
            }
            _ => None,
        };
        self.return_wrapper_aliases
            .entry(item_key(modules, &item.ident.to_string()))
            .or_default()
            .push(ReturnWrapperAliasDefinition {
                module: module_key(modules),
                value_parameter,
                target: (*item.ty).clone(),
            });
    }

    fn collect_imports(&mut self, modules: &[String], item: &ItemUse) {
        let mut entries = Vec::new();
        flatten_use_tree(&item.tree, &mut Vec::new(), &mut entries);
        let mut glob_paths = Vec::new();
        flatten_use_globs(&item.tree, &mut Vec::new(), &mut glob_paths);
        let module = module_key(modules);
        for (alias, raw_path) in entries {
            self.import_bindings
                .entry(module.clone())
                .or_default()
                .entry(alias.clone())
                .or_default()
                .insert(raw_path.clone());
            for path in normalize_import_paths(&module, &raw_path) {
                self.imports
                    .entry(module.clone())
                    .or_default()
                    .entry(alias.clone())
                    .or_default()
                    .insert(path);
            }
        }
        for raw_path in glob_paths {
            for path in normalize_import_paths(&module, &raw_path) {
                self.glob_imports
                    .entry(module.clone())
                    .or_default()
                    .insert(path);
            }
        }
    }

    fn collect_extern_crate(&mut self, modules: &[String], item: &syn::ItemExternCrate) {
        let module = module_key(modules);
        let source = item.ident.to_string();
        let alias = item
            .rename
            .as_ref()
            .map_or_else(|| source.clone(), |(_, alias)| alias.to_string());
        if source == "self" {
            self.self_extern_aliases
                .entry(module.clone())
                .or_default()
                .insert(alias.clone());
        }
        self.import_bindings
            .entry(module.clone())
            .or_default()
            .entry(alias.clone())
            .or_default()
            .insert(vec![source.clone()]);
        self.imports
            .entry(module)
            .or_default()
            .entry(alias)
            .or_default()
            .insert(if source == "self" {
                String::new()
            } else {
                source
            });
    }

    fn collect_raii_fields(
        &mut self,
        crate_name: &str,
        modules: &[String],
        item: &syn::ItemStruct,
    ) {
        let name = item.ident.to_string();
        let public_path = is_public(&item.vis)
            .then(|| self.public_type_path(crate_name, &item_key(modules, &name)))
            .flatten();
        let Some(public_path) = public_path else {
            return;
        };
        let generic_type_parameters = generic_type_parameters([&item.generics]);
        for field in &item.fields {
            if !attributes_are_enabled(&field.attrs, &self.coordinate) {
                continue;
            }
            let mut owned = BTreeSet::new();
            self.collect_owned_type_refs(
                &field.ty,
                &module_key(modules),
                &generic_type_parameters,
                &mut owned,
            );
            self.raii_contains
                .entry(public_path.clone())
                .or_default()
                .extend(owned);
        }
    }

    fn collect_owned_type_refs(
        &self,
        ty: &Type,
        module: &str,
        generic_type_parameters: &BTreeSet<String>,
        owned: &mut BTreeSet<TypeRef>,
    ) {
        match ty {
            Type::Array(array) => {
                self.collect_owned_type_refs(&array.elem, module, generic_type_parameters, owned)
            }
            Type::Group(group) => {
                self.collect_owned_type_refs(&group.elem, module, generic_type_parameters, owned)
            }
            Type::Paren(paren) => {
                self.collect_owned_type_refs(&paren.elem, module, generic_type_parameters, owned)
            }
            Type::Path(path) if path.qself.is_none() => {
                let segments = path_segments(&path.path);
                if segments.is_empty() || path_has_generic_root(&segments, generic_type_parameters)
                {
                    return;
                }
                let reference = TypeRef {
                    module: module.to_owned(),
                    segments,
                };
                owned.insert(reference.clone());
                if !matches!(
                    self.resolve_return_wrapper(&reference),
                    Some(
                        ReturnWrapper::Option
                            | ReturnWrapper::Box
                            | ReturnWrapper::Arc
                            | ReturnWrapper::Rc
                    )
                ) {
                    return;
                }
                for segment in &path.path.segments {
                    let syn::PathArguments::AngleBracketed(arguments) = &segment.arguments else {
                        continue;
                    };
                    for argument in &arguments.args {
                        if let syn::GenericArgument::Type(ty) = argument {
                            self.collect_owned_type_refs(
                                ty,
                                module,
                                generic_type_parameters,
                                owned,
                            );
                        }
                    }
                }
            }
            Type::Slice(slice) => {
                self.collect_owned_type_refs(&slice.elem, module, generic_type_parameters, owned)
            }
            Type::Tuple(tuple) => {
                for element in &tuple.elems {
                    self.collect_owned_type_refs(element, module, generic_type_parameters, owned);
                }
            }
            Type::BareFn(_)
            | Type::ImplTrait(_)
            | Type::Infer(_)
            | Type::Macro(_)
            | Type::Never(_)
            | Type::Ptr(_)
            | Type::Reference(_)
            | Type::TraitObject(_)
            | Type::Verbatim(_) => {}
            _ => {}
        }
    }

    fn path_candidates(&self, module: &str, segments: &[String]) -> BTreeSet<String> {
        let mut candidates = BTreeSet::new();
        let Some(first) = segments.first() else {
            return candidates;
        };
        if first == "crate" || first == &self.crate_name {
            if segments.len() > 1 {
                self.expand_qualified_path(&segments[1..].join("::"), &mut candidates);
            }
            return candidates;
        }
        if first == "self" {
            self.expand_qualified_path(&join_path(module, &segments[1..]), &mut candidates);
            return candidates;
        }
        if first == "super" {
            let mut base = split_path(module);
            let mut offset = 0;
            while segments
                .get(offset)
                .is_some_and(|segment| segment == "super")
            {
                if base.pop().is_none() {
                    return BTreeSet::new();
                }
                offset += 1;
            }
            self.expand_qualified_path(&join_segments(&base, &segments[offset..]), &mut candidates);
            return candidates;
        }
        self.expand_scope_candidates(module, segments, &mut BTreeSet::new(), &mut candidates);
        self.expand_qualified_path(&segments.join("::"), &mut candidates);
        candidates
    }

    fn expand_qualified_path(&self, path: &str, candidates: &mut BTreeSet<String>) {
        candidates.insert(path.to_owned());
        let parts = split_path(path);
        if parts.is_empty() {
            return;
        }
        let module = parts[..parts.len() - 1].join("::");
        self.expand_scope_candidates(
            &module,
            &parts[parts.len() - 1..],
            &mut BTreeSet::new(),
            candidates,
        );
    }

    fn expand_scope_candidates(
        &self,
        module: &str,
        segments: &[String],
        visited: &mut BTreeSet<(String, Vec<String>)>,
        candidates: &mut BTreeSet<String>,
    ) {
        if !visited.insert((module.to_owned(), segments.to_vec())) {
            return;
        }
        candidates.insert(join_path(module, segments));
        let Some(first) = segments.first() else {
            return;
        };
        let explicit_binding = self.imports.get(module).and_then(|items| items.get(first));
        if let Some(imports) = explicit_binding {
            for imported in imports {
                let candidate = join_path(imported, &segments[1..]);
                candidates.insert(candidate.clone());
                let parts = split_path(&candidate);
                if let Some(last) = parts.last() {
                    self.expand_scope_candidates(
                        &parts[..parts.len() - 1].join("::"),
                        std::slice::from_ref(last),
                        visited,
                        candidates,
                    );
                }
            }
        }
        if explicit_binding.is_none()
            && let Some(globs) = self.glob_imports.get(module)
        {
            for imported_module in globs {
                self.expand_scope_candidates(imported_module, segments, visited, candidates);
            }
        }
    }

    fn resolve_type_ref(&self, reference: &TypeRef) -> Option<String> {
        let exact = self
            .path_candidates(&reference.module, &reference.segments)
            .into_iter()
            .filter(|candidate| self.is_declared_type(candidate))
            .collect::<BTreeSet<_>>();
        if exact.len() == 1 {
            return exact.into_iter().next();
        }
        if !exact.is_empty() {
            return None;
        }
        if reference.segments.len() != 1 {
            return None;
        }
        let ident = reference.segments.last()?;
        if self
            .imports
            .get(&reference.module)
            .is_some_and(|imports| imports.contains_key(ident))
            || self
                .local_modules
                .get(&reference.module)
                .is_some_and(|modules| modules.contains(ident))
            || self
                .glob_imports
                .get(&reference.module)
                .is_some_and(|globs| !globs.is_empty())
        {
            return None;
        }
        let candidates = self.declared_types.get(ident)?;
        (candidates.len() == 1)
            .then(|| candidates.first().cloned())
            .flatten()
    }

    fn resolve_return_wrapper(&self, reference: &TypeRef) -> Option<ReturnWrapper> {
        self.resolve_return_wrapper_inner(reference, &mut BTreeSet::new())
    }

    fn resolve_return_wrapper_inner(
        &self,
        reference: &TypeRef,
        visiting_aliases: &mut BTreeSet<String>,
    ) -> Option<ReturnWrapper> {
        let segments = &reference.segments;
        if self.import_binding_is_ambiguous(&reference.module, segments) {
            return None;
        }
        let unqualified = segments.len() == 1;
        let declared = self
            .path_candidates(&reference.module, segments)
            .into_iter()
            .filter(|candidate| self.is_declared_type(candidate))
            .collect::<BTreeSet<_>>();
        if !declared.is_empty() {
            if declared.len() != 1 {
                return None;
            }
            let declaration = declared.first().expect("one declared wrapper candidate");
            return self.resolve_return_wrapper_alias(declaration, visiting_aliases);
        }
        if unqualified {
            let name = segments.first()?;
            if self
                .imports
                .get(&reference.module)
                .is_some_and(|imports| imports.contains_key(name))
            {
                return self.resolve_explicit_standard_wrapper_import(&reference.module, name);
            }
            if self
                .local_modules
                .get(&reference.module)
                .is_some_and(|modules| modules.contains(name))
                || self
                    .glob_imports
                    .get(&reference.module)
                    .is_some_and(|globs| !globs.is_empty())
            {
                return None;
            }
        }
        let direct = standard_return_wrapper(segments);
        if let Some(wrapper) = direct
            && !unqualified
            && !self.name_is_shadowed_in_module(&reference.module, segments.first()?)
        {
            return Some(wrapper);
        }

        let candidates = self.path_candidates(&reference.module, segments);
        let recognized = candidates
            .iter()
            .filter_map(|candidate| standard_return_wrapper(&split_path(candidate)))
            .collect::<BTreeSet<_>>();
        if recognized.len() == 1 {
            let wrapper = *recognized.first().expect("one standard return wrapper");
            if segments
                .first()
                .is_some_and(|root| matches!(root.as_str(), "std" | "core" | "alloc"))
                && self.name_is_shadowed_in_module(&reference.module, segments.first()?)
            {
                return None;
            }
            return Some(wrapper);
        }

        if !unqualified {
            return None;
        }
        let name = segments.first()?;
        matches!(name.as_str(), "Result" | "Option" | "Box")
            .then(|| standard_return_wrapper(segments))
            .flatten()
    }

    fn resolve_explicit_standard_wrapper_import(
        &self,
        module: &str,
        name: &str,
    ) -> Option<ReturnWrapper> {
        let sources = self.import_bindings.get(module)?.get(name)?;
        let source = (sources.len() == 1).then(|| sources.first()).flatten()?;
        let root = source.first()?;
        (!self.root_name_is_shadowed(module, root))
            .then(|| standard_return_wrapper(source))
            .flatten()
    }

    fn must_invoke_requirement_is_proven(
        &self,
        context_index: usize,
        requirement: &MustInvokeRequirement,
        resolved_owners: &[Option<String>],
        by_module_ident: &BTreeMap<(String, String), Vec<usize>>,
        by_owner_ident: &BTreeMap<(String, String), Vec<usize>>,
    ) -> bool {
        match requirement {
            MustInvokeRequirement::ResultCall(target) => {
                let Some(ResolvedTarget::Node(target_index)) = self.resolve_call_target(
                    context_index,
                    target,
                    &ParameterBindings::new(),
                    resolved_owners,
                    by_module_ident,
                    by_owner_ident,
                ) else {
                    return false;
                };
                self.nodes[target_index]
                    .must_invoke_result_wrapper
                    .as_ref()
                    .is_some_and(|wrapper| {
                        self.resolve_return_wrapper(wrapper) == Some(ReturnWrapper::Result)
                    })
            }
            MustInvokeRequirement::ResultErrConstructor(segments) => {
                self.result_err_constructor_is_proven(&self.nodes[context_index].module, segments)
            }
        }
    }

    fn result_err_constructor_is_proven(&self, module: &str, segments: &[String]) -> bool {
        self.result_variant_constructor_is_proven(module, segments, "Err")
    }

    fn result_ok_constructor_is_proven(&self, module: &str, segments: &[String]) -> bool {
        self.result_variant_constructor_is_proven(module, segments, "Ok")
    }

    fn result_variant_constructor_is_proven(
        &self,
        module: &str,
        segments: &[String],
        variant_name: &str,
    ) -> bool {
        let Some((variant, wrapper)) = segments.split_last() else {
            return false;
        };
        if variant != variant_name {
            return false;
        }
        if !wrapper.is_empty() {
            return self.resolve_return_wrapper(&TypeRef {
                module: module.to_owned(),
                segments: wrapper.to_vec(),
            }) == Some(ReturnWrapper::Result);
        }
        !self
            .imports
            .get(module)
            .is_some_and(|imports| imports.contains_key(variant_name))
            && !self
                .glob_imports
                .get(module)
                .is_some_and(|imports| !imports.is_empty())
            && !self
                .local_modules
                .get(module)
                .is_some_and(|modules| modules.contains(variant_name))
            && !self
                .declared_type_paths
                .contains(&join_path(module, &[variant_name.to_owned()]))
            && !self
                .declared_value_paths
                .contains(&join_path(module, &[variant_name.to_owned()]))
    }

    fn resolve_return_wrapper_alias(
        &self,
        declaration: &str,
        visiting_aliases: &mut BTreeSet<String>,
    ) -> Option<ReturnWrapper> {
        if !visiting_aliases.insert(declaration.to_owned()) {
            return None;
        }
        let resolved = (|| {
            let [definition] = self.return_wrapper_aliases.get(declaration)?.as_slice() else {
                return None;
            };
            let parameter = definition.value_parameter.as_deref()?;
            let target = transparent_return_wrapper_alias_target(
                &definition.target,
                &definition.module,
                parameter,
            )?;
            self.resolve_return_wrapper_inner(&target, visiting_aliases)
        })();
        visiting_aliases.remove(declaration);
        resolved
    }

    fn is_declared_type(&self, path: &str) -> bool {
        self.declared_type_paths.contains(path)
    }

    fn is_proven_boxdd_ffi_function_path(&self, module: &str, segments: &[String]) -> bool {
        self.has_boxdd_sys_dependency
            && is_boxdd_ffi_function_path_shape(segments)
            && !self.boxdd_sys_is_shadowed(module)
    }

    fn resolve_ffi_type_ref(&self, reference: &TypeRef) -> Option<String> {
        if !self.has_boxdd_sys_dependency || self.boxdd_sys_is_shadowed(&reference.module) {
            return None;
        }
        if self.import_binding_is_ambiguous(&reference.module, &reference.segments) {
            return None;
        }
        let candidates = self.path_candidates(&reference.module, &reference.segments);
        if candidates
            .iter()
            .any(|candidate| self.is_declared_type(candidate))
        {
            return None;
        }
        let raw_types = candidates
            .into_iter()
            .filter(|candidate| is_boxdd_ffi_type_path_shape(&split_path(candidate)))
            .collect::<BTreeSet<_>>();
        (raw_types.len() == 1)
            .then(|| raw_types.into_iter().next())
            .flatten()
    }

    fn resolve_ffi_function_return(&self, module: &str, segments: &[String]) -> Option<TypeRef> {
        self.resolve_ffi_function(module, segments)
            .map(|(_, return_type)| return_type)
    }

    fn resolve_ffi_function(&self, module: &str, segments: &[String]) -> Option<(String, TypeRef)> {
        if !self.has_boxdd_sys_dependency
            || self.boxdd_sys_is_shadowed(module)
            || self.import_binding_is_ambiguous(module, segments)
        {
            return None;
        }
        let candidates = self.path_candidates(module, segments);
        if candidates
            .iter()
            .any(|candidate| self.declared_value_paths.contains(candidate))
        {
            return None;
        }
        let returns = candidates
            .into_iter()
            .filter(|candidate| is_boxdd_ffi_function_path_shape(&split_path(candidate)))
            .filter_map(|candidate| {
                self.ffi_type_hints
                    .function_returns
                    .get(&candidate)
                    .filter(|return_type| is_boxdd_ffi_type_path_shape(&split_path(return_type)))
                    .map(|return_type| (candidate, return_type.clone()))
            })
            .collect::<BTreeMap<_, _>>();
        (returns.len() == 1).then(|| {
            let (function, return_type) = returns.first_key_value().expect("one FFI return type");
            (
                function.clone(),
                TypeRef {
                    module: module.to_owned(),
                    segments: split_path(return_type),
                },
            )
        })
    }

    fn boxdd_sys_is_shadowed(&self, module: &str) -> bool {
        let mut scope = split_path(module);
        let mut visited = BTreeSet::new();
        loop {
            if self.scope_shadows_boxdd_sys(&scope.join("::"), &mut visited) {
                return true;
            }
            if scope.pop().is_none() {
                return false;
            }
        }
    }

    fn import_binding_is_ambiguous(&self, module: &str, segments: &[String]) -> bool {
        let Some(first) = segments.first() else {
            return false;
        };
        self.import_bindings
            .get(module)
            .and_then(|bindings| bindings.get(first))
            .is_some_and(|sources| sources.len() != 1)
    }

    fn scope_shadows_boxdd_sys(&self, module: &str, visited: &mut BTreeSet<String>) -> bool {
        if !visited.insert(module.to_owned()) {
            return false;
        }
        if self
            .local_modules
            .get(module)
            .is_some_and(|modules| modules.contains("boxdd_sys"))
            || self
                .self_extern_aliases
                .get(module)
                .is_some_and(|aliases| aliases.contains("boxdd_sys"))
            || self
                .imports
                .get(module)
                .and_then(|imports| imports.get("boxdd_sys"))
                .is_some_and(|paths| !paths.contains("boxdd_sys"))
        {
            return true;
        }

        self.glob_imports.get(module).is_some_and(|imports| {
            imports.iter().any(|imported_module| {
                self.is_declared_module(imported_module)
                    && self.scope_shadows_boxdd_sys(imported_module, visited)
            })
        })
    }

    fn is_declared_module(&self, path: &str) -> bool {
        let mut segments = split_path(path);
        let Some(name) = segments.pop() else {
            return true;
        };
        self.local_modules
            .get(&segments.join("::"))
            .is_some_and(|modules| modules.contains(&name))
    }

    fn resolve_call_target(
        &self,
        caller_index: usize,
        target: &CallTarget,
        parameter_bindings: &BTreeMap<usize, ResolvedTarget>,
        resolved_owners: &[Option<String>],
        by_module_ident: &BTreeMap<(String, String), Vec<usize>>,
        by_owner_ident: &BTreeMap<(String, String), Vec<usize>>,
    ) -> Option<ResolvedTarget> {
        let caller = &self.nodes[caller_index];
        let mut targets = BTreeSet::new();
        match target {
            CallTarget::ReturnedCall { target, arguments } => {
                let Some(ResolvedTarget::Node(returning_node)) = self.resolve_call_target(
                    caller_index,
                    target,
                    parameter_bindings,
                    resolved_owners,
                    by_module_ident,
                    by_owner_ident,
                ) else {
                    return None;
                };
                let returned = self.nodes[returning_node].callable_return.as_ref()?;
                let returned_bindings = arguments
                    .iter()
                    .enumerate()
                    .filter_map(|(index, argument)| {
                        self.resolve_call_target(
                            caller_index,
                            argument.as_ref()?,
                            parameter_bindings,
                            resolved_owners,
                            by_module_ident,
                            by_owner_ident,
                        )
                        .map(|target| (index, target))
                    })
                    .collect::<ParameterBindings>();
                if let Some(target) = self.resolve_call_target(
                    returning_node,
                    returned,
                    &returned_bindings,
                    resolved_owners,
                    by_module_ident,
                    by_owner_ident,
                ) {
                    targets.insert(target);
                }
            }
            CallTarget::StaticArrayIndex { segments } => {
                if let Some(target) = self.resolve_static_callable_array(
                    caller_index,
                    segments,
                    parameter_bindings,
                    resolved_owners,
                    by_module_ident,
                    by_owner_ident,
                ) {
                    targets.insert(target);
                }
            }
            CallTarget::CatchUnwind { root, callback } => {
                if matches!(root.as_str(), "core" | "std")
                    && !self.root_name_is_shadowed(&caller.module, root)
                    && let Some(target) = self.resolve_call_target(
                        caller_index,
                        callback,
                        parameter_bindings,
                        resolved_owners,
                        by_module_ident,
                        by_owner_ident,
                    )
                {
                    targets.insert(target);
                }
            }
            CallTarget::OptionSome { wrapper, value } => {
                if self.option_some_is_unshadowed(&caller.module, wrapper, by_module_ident)
                    && let Some(target) = self.resolve_call_target(
                        caller_index,
                        value,
                        parameter_bindings,
                        resolved_owners,
                        by_module_ident,
                        by_owner_ident,
                    )
                {
                    targets.insert(target);
                }
            }
            CallTarget::Closure(summary) => {
                targets.insert(ResolvedTarget::Closure {
                    definition_node: caller_index,
                    summary: summary.clone(),
                });
            }
            CallTarget::Parameter(index) => {
                if let Some(target) = parameter_bindings.get(index) {
                    targets.insert(target.clone());
                }
            }
            CallTarget::Method { ident, receiver } => {
                let owner = match receiver {
                    MethodReceiver::CurrentOwner => resolved_owners[caller_index].clone(),
                    MethodReceiver::ExplicitType(segments) => self.resolve_type_ref(&TypeRef {
                        module: caller.module.clone(),
                        segments: segments.clone(),
                    }),
                };
                if let Some(owner) = owner
                    && let Some(nodes) = by_owner_ident.get(&(owner, ident.clone()))
                {
                    targets.extend(nodes.iter().copied().map(ResolvedTarget::Node));
                }
            }
            CallTarget::Path { segments, qself } => {
                let ident = segments.last()?;
                if let Some(qself) = qself {
                    if let Some(owner) = self.resolve_type_ref(&TypeRef {
                        module: caller.module.clone(),
                        segments: qself.clone(),
                    }) && let Some(nodes) = by_owner_ident.get(&(owner, ident.clone()))
                    {
                        targets.extend(nodes.iter().copied().map(ResolvedTarget::Node));
                    }
                } else if segments.first().is_some_and(|segment| segment == "Self") {
                    if segments.len() == 2
                        && let Some(owner) = &resolved_owners[caller_index]
                        && let Some(nodes) = by_owner_ident.get(&(owner.clone(), ident.clone()))
                    {
                        targets.extend(nodes.iter().copied().map(ResolvedTarget::Node));
                    }
                } else {
                    let can_resolve_external_crate = !segments.first().is_some_and(|segment| {
                        matches!(segment.as_str(), "crate" | "self" | "super" | "Self")
                    }) && !self
                        .import_binding_is_ambiguous(&caller.module, segments);
                    for candidate in self.path_candidates(&caller.module, segments) {
                        let parts = split_path(&candidate);
                        let Some(target_ident) = parts.last() else {
                            continue;
                        };
                        if can_resolve_external_crate
                            && self.is_proven_boxdd_ffi_function_path(&caller.module, &parts)
                        {
                            targets.insert(ResolvedTarget::CSymbol(target_ident.clone()));
                        }
                        let target_module = parts[..parts.len() - 1].join("::");
                        if let Some(nodes) =
                            by_module_ident.get(&(target_module.clone(), target_ident.clone()))
                        {
                            targets.extend(nodes.iter().copied().map(ResolvedTarget::Node));
                        }
                        if parts.len() > 1 {
                            let owner = parts[..parts.len() - 1].join("::");
                            if self.is_declared_type(&owner)
                                && let Some(nodes) =
                                    by_owner_ident.get(&(owner, target_ident.clone()))
                            {
                                targets.extend(nodes.iter().copied().map(ResolvedTarget::Node));
                            }
                        }
                    }
                    if segments.len() > 1 {
                        let owner_ref = TypeRef {
                            module: caller.module.clone(),
                            segments: segments[..segments.len() - 1].to_vec(),
                        };
                        if let Some(owner) = self.resolve_type_ref(&owner_ref)
                            && let Some(nodes) = by_owner_ident.get(&(owner, ident.clone()))
                        {
                            targets.extend(nodes.iter().copied().map(ResolvedTarget::Node));
                        }
                    }
                }
            }
        }
        (targets.len() == 1)
            .then(|| targets.into_iter().next())
            .flatten()
    }

    #[allow(clippy::too_many_arguments)]
    fn resolve_static_callable_array(
        &self,
        caller_index: usize,
        segments: &[String],
        parameter_bindings: &ParameterBindings,
        resolved_owners: &[Option<String>],
        by_module_ident: &BTreeMap<(String, String), Vec<usize>>,
        by_owner_ident: &BTreeMap<(String, String), Vec<usize>>,
    ) -> Option<ResolvedTarget> {
        let caller = &self.nodes[caller_index];
        let declarations = self
            .path_candidates(&caller.module, segments)
            .into_iter()
            .filter(|candidate| self.static_callable_arrays.contains_key(candidate))
            .collect::<BTreeSet<_>>();
        if declarations.len() != 1 {
            return None;
        }
        let declaration = declarations.first().expect("one static array declaration");
        let [definition] = self.static_callable_arrays.get(declaration)?.as_slice() else {
            return None;
        };
        let mut calls = BTreeSet::new();
        for element in &definition.elements {
            let CallTarget::Path {
                segments,
                qself: None,
            } = element
            else {
                return None;
            };
            let candidates = self
                .path_candidates(&definition.module, segments)
                .into_iter()
                .filter(|candidate| self.declared_value_paths.contains(candidate))
                .collect::<BTreeSet<_>>();
            if candidates.len() != 1 {
                return None;
            }
            let target = CallTarget::Path {
                segments: split_path(candidates.first().expect("one static callable")),
                qself: None,
            };
            if !matches!(
                self.resolve_call_target(
                    caller_index,
                    &target,
                    parameter_bindings,
                    resolved_owners,
                    by_module_ident,
                    by_owner_ident,
                ),
                Some(ResolvedTarget::Node(_) | ResolvedTarget::Closure { .. })
            ) {
                return None;
            }
            calls.insert(CallRef {
                target,
                arguments: Vec::new(),
                callable_field_arguments: BTreeMap::new(),
                parameter_offset: 0,
                adapter_flow: AdapterFlow::Untracked,
                owned_output_parameter: None,
            });
        }
        Some(ResolvedTarget::Closure {
            definition_node: caller_index,
            summary: Box::new(ClosureSummary {
                calls,
                captured_value_parameters: BTreeMap::new(),
            }),
        })
    }

    fn option_some_is_unshadowed(
        &self,
        module: &str,
        wrapper: &[String],
        by_module_ident: &BTreeMap<(String, String), Vec<usize>>,
    ) -> bool {
        match wrapper {
            [some] if some == "Some" => {
                !by_module_ident.contains_key(&(module.to_owned(), some.clone()))
                    && !self
                        .imports
                        .get(module)
                        .is_some_and(|imports| imports.contains_key(some))
                    && !self
                        .local_modules
                        .get(module)
                        .is_some_and(|modules| modules.contains(some))
                    && !self.is_declared_type(&join_path(module, wrapper))
            }
            [option, some] if option == "Option" && some == "Some" => {
                self.resolve_type_ref(&TypeRef {
                    module: module.to_owned(),
                    segments: vec![option.clone()],
                })
                .is_none()
                    && !self
                        .imports
                        .get(module)
                        .is_some_and(|imports| imports.contains_key(option))
            }
            [root, option, enum_name, some]
                if matches!(root.as_str(), "core" | "std")
                    && option == "option"
                    && enum_name == "Option"
                    && some == "Some" =>
            {
                !self.root_name_is_shadowed(module, root)
            }
            _ => false,
        }
    }

    fn root_name_is_shadowed(&self, module: &str, name: &str) -> bool {
        let mut scope = split_path(module);
        loop {
            let scope_key = scope.join("::");
            if self
                .local_modules
                .get(&scope_key)
                .is_some_and(|modules| modules.contains(name))
                || self
                    .self_extern_aliases
                    .get(&scope_key)
                    .is_some_and(|aliases| aliases.contains(name))
                || self
                    .imports
                    .get(&scope_key)
                    .is_some_and(|imports| imports.contains_key(name))
            {
                return true;
            }
            if scope.pop().is_none() {
                return false;
            }
        }
    }

    fn name_is_shadowed_in_module(&self, module: &str, name: &str) -> bool {
        self.local_modules
            .get(module)
            .is_some_and(|modules| modules.contains(name))
            || self
                .self_extern_aliases
                .get(module)
                .is_some_and(|aliases| aliases.contains(name))
            || self
                .imports
                .get(module)
                .is_some_and(|imports| imports.contains_key(name))
    }

    fn finish(self) -> RustIndex {
        let mut public_callable_counts = BTreeMap::<String, usize>::new();
        for node in &self.nodes {
            if !node.is_drop
                && let Some(public_path) = &node.public_path
            {
                *public_callable_counts
                    .entry(public_path.clone())
                    .or_default() += 1;
            }
        }
        let ambiguous_public_callables = public_callable_counts
            .into_iter()
            .filter_map(|(path, count)| (count > 1).then_some(path))
            .collect::<BTreeSet<_>>();
        let public_callable_paths = self
            .public_callable_paths
            .iter()
            .filter(|path| !ambiguous_public_callables.contains(*path))
            .cloned()
            .collect::<BTreeSet<_>>();
        let public_safe_callable_paths = self
            .public_safe_callable_paths
            .iter()
            .filter(|path| !ambiguous_public_callables.contains(*path))
            .cloned()
            .collect::<BTreeSet<_>>();
        let resolved_owners = self
            .nodes
            .iter()
            .map(|node| {
                node.owner
                    .as_ref()
                    .filter(|owner| {
                        !type_ref_has_generic_root(owner, &node.generic_type_parameters)
                    })
                    .and_then(|owner| self.resolve_type_ref(owner))
            })
            .collect::<Vec<_>>();
        let mut by_module_ident: BTreeMap<(String, String), Vec<usize>> = BTreeMap::new();
        let mut by_owner_ident: BTreeMap<(String, String), Vec<usize>> = BTreeMap::new();
        for (index, node) in self.nodes.iter().enumerate() {
            if node.owner.is_none() {
                by_module_ident
                    .entry((node.module.clone(), node.ident.clone()))
                    .or_default()
                    .push(index);
            }
            if let Some(owner) = &resolved_owners[index] {
                by_owner_ident
                    .entry((owner.clone(), node.ident.clone()))
                    .or_default()
                    .push(index);
            }
        }
        let mut symbol_paths: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
        let mut callable_argument_symbol_paths = BTreeMap::new();
        let mut callable_field_argument_symbol_paths = BTreeMap::new();
        let mut ffi_type_paths: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
        let mut ffi_field_paths: BTreeMap<(String, String), BTreeSet<String>> = BTreeMap::new();
        let mut safe_ffi_type_paths: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
        let mut safe_ffi_field_paths: BTreeMap<(String, String), BTreeSet<String>> =
            BTreeMap::new();
        let mut safe_ffi_type_paths_by_producer = BTreeMap::new();
        let mut safe_ffi_field_paths_by_producer = BTreeMap::new();
        let mut ignored_safe_type_provenance = BTreeMap::new();
        let mut ignored_safe_field_provenance = BTreeMap::new();
        let resolved_node_abi =
            resolve_node_abi(&self, &resolved_owners, &by_module_ident, &by_owner_ident);
        let public_roots = self
            .nodes
            .iter()
            .enumerate()
            .filter_map(|(index, node)| {
                node.public_path
                    .as_ref()
                    .filter(|path| !ambiguous_public_callables.contains(*path))
                    .map(|public_path| (index, public_path.clone()))
            })
            .collect::<Vec<_>>();
        trace_reachable(
            &self,
            &resolved_node_abi,
            false,
            &public_roots,
            &resolved_owners,
            &by_module_ident,
            &by_owner_ident,
            &mut symbol_paths,
            &mut callable_argument_symbol_paths,
            &mut callable_field_argument_symbol_paths,
            &mut ffi_type_paths,
            &mut ffi_field_paths,
            &mut ignored_safe_type_provenance,
            &mut ignored_safe_field_provenance,
        );
        let safe_public_roots = public_roots
            .iter()
            .filter(|(_, public_path)| public_safe_callable_paths.contains(public_path))
            .cloned()
            .collect::<Vec<_>>();
        let mut safe_symbols = BTreeMap::new();
        let mut safe_callable_arguments = BTreeMap::new();
        let mut safe_callable_fields = BTreeMap::new();
        trace_reachable(
            &self,
            &resolved_node_abi,
            true,
            &safe_public_roots,
            &resolved_owners,
            &by_module_ident,
            &by_owner_ident,
            &mut safe_symbols,
            &mut safe_callable_arguments,
            &mut safe_callable_fields,
            &mut safe_ffi_type_paths,
            &mut safe_ffi_field_paths,
            &mut safe_ffi_type_paths_by_producer,
            &mut safe_ffi_field_paths_by_producer,
        );
        for (owner, storage) in &self.raw_storage_by_owner {
            let Some(public_path) = self.canonical_public_paths.get(owner) else {
                continue;
            };
            for storage in storage {
                if let Some(raw_type) = self.resolve_ffi_type_ref(&storage.raw_type) {
                    ffi_type_paths
                        .entry(raw_type)
                        .or_default()
                        .insert(public_path.clone());
                    safe_ffi_type_paths
                        .entry(
                            self.resolve_ffi_type_ref(&storage.raw_type)
                                .expect("resolved above"),
                        )
                        .or_default()
                        .insert(public_path.clone());
                }
            }
        }

        let mut conversion_roots = Vec::new();
        for (owner, public_path) in &self.canonical_public_paths {
            for (index, node) in self.nodes.iter().enumerate() {
                if resolved_owners[index].as_ref() == Some(owner)
                    && is_abi_conversion_method(&node.ident)
                {
                    conversion_roots.push((index, public_path.clone()));
                }
            }
        }
        if !conversion_roots.is_empty() {
            let mut conversion_symbols = BTreeMap::new();
            let mut conversion_callable_arguments = BTreeMap::new();
            let mut conversion_callable_fields = BTreeMap::new();
            let mut conversion_fields = BTreeMap::new();
            trace_reachable(
                &self,
                &resolved_node_abi,
                false,
                &conversion_roots,
                &resolved_owners,
                &by_module_ident,
                &by_owner_ident,
                &mut conversion_symbols,
                &mut conversion_callable_arguments,
                &mut conversion_callable_fields,
                &mut ffi_type_paths,
                &mut conversion_fields,
                &mut ignored_safe_type_provenance,
                &mut ignored_safe_field_provenance,
            );
        }
        let safe_conversion_roots = conversion_roots
            .iter()
            .filter(|(index, _)| {
                self.nodes[*index]
                    .public_path
                    .as_ref()
                    .is_some_and(|path| public_safe_callable_paths.contains(path))
            })
            .cloned()
            .collect::<Vec<_>>();
        if !safe_conversion_roots.is_empty() {
            let mut conversion_symbols = BTreeMap::new();
            let mut conversion_callable_arguments = BTreeMap::new();
            let mut conversion_callable_fields = BTreeMap::new();
            let mut conversion_fields = BTreeMap::new();
            trace_reachable(
                &self,
                &resolved_node_abi,
                true,
                &safe_conversion_roots,
                &resolved_owners,
                &by_module_ident,
                &by_owner_ident,
                &mut conversion_symbols,
                &mut conversion_callable_arguments,
                &mut conversion_callable_fields,
                &mut safe_ffi_type_paths,
                &mut conversion_fields,
                &mut safe_ffi_type_paths_by_producer,
                &mut safe_ffi_field_paths_by_producer,
            );
        }

        let mut capability_gated_conversion_paths = BTreeSet::new();
        for (owner, public_path) in &self.canonical_public_paths {
            for (index, node) in self.nodes.iter().enumerate() {
                if resolved_owners[index].as_deref() == Some(owner)
                    && closest_ray_result_conversion_is_capability_gated(
                        &self,
                        node,
                        owner,
                        public_path,
                    )
                {
                    capability_gated_conversion_paths.insert(public_path.clone());
                }
            }
        }
        record_capability_gated_closest_ray_witnesses(
            &capability_gated_conversion_paths,
            &mut safe_ffi_field_paths,
        );

        for node in &self.nodes {
            for field in node.abi_fields.iter().filter(|field| field.observable) {
                let (Some(safe_owner), Some(safe_field)) = (&field.safe_owner, &field.safe_field)
                else {
                    continue;
                };
                let Some(owner) = self.resolve_type_ref(safe_owner) else {
                    continue;
                };
                if !self
                    .public_fields_by_owner
                    .get(&owner)
                    .is_some_and(|fields| fields.contains(safe_field))
                {
                    continue;
                }
                let Some(public_owner) = self.canonical_public_paths.get(&owner) else {
                    continue;
                };
                let Some(raw_type) = self.resolve_ffi_type_ref(&field.raw_type) else {
                    continue;
                };
                let public_field = format!("{public_owner}::{safe_field}");
                if self.public_field_paths.contains(&public_field) {
                    ffi_field_paths
                        .entry((raw_type, field.raw_field_chain.clone()))
                        .or_default()
                        .insert(public_field.clone());
                    if node
                        .public_path
                        .as_ref()
                        .is_some_and(|path| public_safe_callable_paths.contains(path))
                    {
                        safe_ffi_field_paths
                            .entry((
                                self.resolve_ffi_type_ref(&field.raw_type)
                                    .expect("resolved above"),
                                field.raw_field_chain.clone(),
                            ))
                            .or_default()
                            .insert(public_field);
                    }
                }
            }
        }
        let mut raii_roots = Vec::new();
        for (public_path, contained_types) in &self.raii_contains {
            for contained_type in contained_types {
                let Some(owner) = self.resolve_type_ref(contained_type) else {
                    continue;
                };
                let drop_nodes = self
                    .nodes
                    .iter()
                    .enumerate()
                    .filter_map(|(index, node)| {
                        (node.is_drop && resolved_owners[index].as_ref() == Some(&owner))
                            .then_some(index)
                    })
                    .collect::<Vec<_>>();
                if drop_nodes.len() == 1 {
                    raii_roots.push((drop_nodes[0], public_path.clone()));
                }
            }
        }
        if !raii_roots.is_empty() {
            let mut raii_types = BTreeMap::new();
            let mut raii_fields = BTreeMap::new();
            trace_reachable(
                &self,
                &resolved_node_abi,
                false,
                &raii_roots,
                &resolved_owners,
                &by_module_ident,
                &by_owner_ident,
                &mut symbol_paths,
                &mut callable_argument_symbol_paths,
                &mut callable_field_argument_symbol_paths,
                &mut raii_types,
                &mut raii_fields,
                &mut ignored_safe_type_provenance,
                &mut ignored_safe_field_provenance,
            );
        }
        strip_reserved_event_safe_provenance(
            &mut safe_ffi_type_paths,
            &mut safe_ffi_field_paths,
            &mut safe_ffi_type_paths_by_producer,
            &mut safe_ffi_field_paths_by_producer,
        );
        add_published_slot_provenance(
            &self,
            &safe_public_roots,
            &resolved_owners,
            &by_module_ident,
            &by_owner_ident,
            &mut safe_ffi_type_paths,
            &mut safe_ffi_field_paths,
            &mut safe_ffi_type_paths_by_producer,
            &mut safe_ffi_field_paths_by_producer,
        );
        add_mover_plane_callback_provenance(
            &self,
            &safe_public_roots,
            &resolved_node_abi,
            &resolved_owners,
            &by_module_ident,
            &by_owner_ident,
            &mut safe_ffi_type_paths,
            &mut safe_ffi_field_paths,
            &mut safe_ffi_type_paths_by_producer,
            &mut safe_ffi_field_paths_by_producer,
        );
        let public_type_paths = self
            .public_type_declarations
            .iter()
            .filter_map(|declaration| self.canonical_public_paths.get(declaration).cloned())
            .collect();
        let mut must_invoke_candidates = BTreeMap::<String, BTreeSet<usize>>::new();
        let mut must_invoke_duplicates = BTreeSet::new();
        for (index, node) in self.nodes.iter().enumerate() {
            let Some(public_path) = &node.public_path else {
                continue;
            };
            if ambiguous_public_callables.contains(public_path) {
                continue;
            }
            let Some(result_wrapper) = &node.must_invoke_result_wrapper else {
                continue;
            };
            if self.resolve_return_wrapper(result_wrapper) != Some(ReturnWrapper::Result) {
                continue;
            }
            let proven_arguments = node
                .must_invoke_callable_arguments
                .iter()
                .filter_map(|(argument, requirements)| {
                    requirements
                        .iter()
                        .all(|requirement| {
                            self.must_invoke_requirement_is_proven(
                                index,
                                requirement,
                                &resolved_owners,
                                &by_module_ident,
                                &by_owner_ident,
                            )
                        })
                        .then_some(*argument)
                })
                .collect::<BTreeSet<_>>();
            if let Some(previous) = must_invoke_candidates.get_mut(public_path) {
                *previous = previous.intersection(&proven_arguments).copied().collect();
                must_invoke_duplicates.insert(public_path.clone());
            } else {
                must_invoke_candidates.insert(public_path.clone(), proven_arguments);
            }
        }
        let must_invoke_callable_arguments = must_invoke_candidates
            .into_iter()
            .filter(|(public_path, arguments)| {
                !arguments.is_empty() && !must_invoke_duplicates.contains(public_path)
            })
            .collect();
        let mut callable_evidence_signature_candidates =
            BTreeMap::<String, BTreeSet<CallableEvidenceSignature>>::new();
        for node in &self.nodes {
            let (Some(public_path), Some(signature)) =
                (&node.public_path, &node.callable_evidence_signature)
            else {
                continue;
            };
            if ambiguous_public_callables.contains(public_path)
                || !public_safe_callable_paths.contains(public_path)
            {
                continue;
            }
            callable_evidence_signature_candidates
                .entry(public_path.clone())
                .or_default()
                .insert(signature.clone());
        }
        let callable_evidence_signatures = callable_evidence_signature_candidates
            .into_iter()
            .filter_map(|(path, candidates)| {
                (candidates.len() == 1).then(|| {
                    (
                        path,
                        candidates
                            .into_iter()
                            .next()
                            .expect("one callable signature"),
                    )
                })
            })
            .collect();
        let mut callable_return_candidates =
            BTreeMap::<String, BTreeSet<CallableReturnType>>::new();
        for node in &self.nodes {
            let Some(public_path) = &node.public_path else {
                continue;
            };
            if ambiguous_public_callables.contains(public_path) {
                continue;
            }
            let Some(return_type) = &node.return_type else {
                continue;
            };
            let Some(declaration) = self.resolve_type_ref(&return_type.value) else {
                continue;
            };
            let Some(public_type) = self.canonical_public_paths.get(&declaration) else {
                continue;
            };
            let Some(wrappers) = return_type
                .wrappers
                .iter()
                .map(|wrapper| self.resolve_return_wrapper(wrapper))
                .collect::<Option<Vec<_>>>()
            else {
                continue;
            };
            callable_return_candidates
                .entry(public_path.clone())
                .or_default()
                .insert(CallableReturnType {
                    owner: public_type.clone(),
                    wrappers,
                    owned: return_type.owned,
                });
        }
        let callable_return_types = callable_return_candidates
            .into_iter()
            .filter_map(|(path, candidates)| {
                (candidates.len() == 1).then(|| {
                    (
                        path,
                        candidates.into_iter().next().expect("one return type"),
                    )
                })
            })
            .collect();
        RustIndex {
            public_paths: self.public_paths,
            public_type_paths,
            public_callable_paths,
            public_safe_callable_paths,
            public_field_paths: self.public_field_paths,
            public_alias_paths: self.public_alias_paths,
            callable_evidence_signatures,
            callable_return_types,
            must_invoke_callable_arguments,
            symbol_paths,
            callable_argument_symbol_paths,
            callable_field_argument_symbol_paths,
            ffi_type_paths,
            ffi_field_paths,
            safe_ffi_type_paths,
            safe_ffi_field_paths,
            safe_ffi_type_paths_by_producer,
            safe_ffi_field_paths_by_producer,
        }
    }
}

type ParameterBindings = BTreeMap<usize, ResolvedTarget>;
type TraceBindingKey = (usize, ResolvedTarget);
type ResolvedCallEdges = Vec<ResolvedCallEdge>;

#[derive(Clone)]
struct ResolvedCallEdge {
    target: ResolvedTarget,
    target_bindings: ParameterBindings,
    callable_arguments: BTreeSet<usize>,
    callable_field_arguments: BTreeSet<(usize, String)>,
    adapter_flow: AdapterFlow,
    owned_output_parameter: Option<usize>,
    value_parameter_arguments: BTreeMap<usize, usize>,
}

#[derive(Default)]
struct ResolvedNodeAbi {
    types: BTreeSet<String>,
    observable_types: BTreeSet<String>,
    fields: BTreeSet<ResolvedAbiField>,
}

#[derive(Clone, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct ResolvedAbiField {
    raw_type: String,
    raw_field_chain: String,
    safe_public_owner: Option<String>,
    safe_public_field: Option<String>,
    observable: bool,
}

#[derive(Clone, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct OwnedSlotRelation {
    capture_node: usize,
    decoder_node: usize,
    decoder_raw_type: String,
    brand_parameter: usize,
    epoch_parameter: Option<usize>,
    slot_owner: String,
    slot_field: String,
    raw_parameter: usize,
    raw_type: String,
    raw_field_chain: String,
}

#[derive(Clone, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct SnapshotSlotRelation {
    snapshot_capture_node: usize,
    raw_snapshot_owner: String,
    raw_snapshot_field: String,
    raw_snapshot_parameter: usize,
    snapshot_brand_parameter: usize,
    snapshot_epoch_parameter: Option<usize>,
    snapshot_owner: String,
    snapshot_field: String,
    slot_owner: String,
    slot_field: String,
    raw_type: String,
    raw_field_chain: String,
}

#[derive(Clone, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct SnapshotPublication {
    publisher_node: usize,
    cache_owner: String,
    cache_storage_field: String,
    published_field: String,
    snapshot_owner: String,
    snapshot_parameter: usize,
    accessor_node: usize,
}

#[derive(Clone, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct PublishedCapture {
    bridge_node: usize,
    cache_parameter: usize,
    world_parameter: usize,
    brand_parameter: usize,
    epoch_parameter: Option<usize>,
    snapshot_capture_node: usize,
    snapshot_owner: String,
    accessor_node: usize,
}

#[derive(Clone, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct WorldEventAccessContract {
    world_owner: String,
    core_owner: String,
    raw_accessor: usize,
    brand_accessor: usize,
    cache_accessor: usize,
}

#[derive(Clone, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct WorldStepBridge {
    step_node: usize,
    bridge_node: usize,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct RawSnapshotCapture {
    owner: String,
    world_parameter: usize,
    getters_by_field: BTreeMap<String, String>,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct OwnedAdapterProtocol {
    owned_parameter: usize,
    pointer_parameter: usize,
    count_parameter: usize,
    mapper_parameter: usize,
}

#[derive(Clone, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct EventInnerRelation {
    capture_node: usize,
    slot_owner: String,
    slot_field: String,
    raw_type: String,
    raw_field: String,
    safe_type: String,
    safe_field: String,
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct InlineEventDecoder {
    decoder_node: usize,
    decoder_raw_type: String,
    brand_parameter: usize,
    epoch_parameter: Option<usize>,
}

