fn event_protocol_reserves_raw_type(raw_type: &str) -> bool {
    EVENT_CONTAINER_FIELD_PAIRS
        .iter()
        .any(|(container, _, _)| *container == raw_type)
        || EVENT_INNER_FIELD_SPECS
            .iter()
            .any(|(inner, _, _, _)| *inner == raw_type)
}

fn strip_reserved_event_safe_provenance(
    safe_type_paths: &mut BTreeMap<String, BTreeSet<String>>,
    safe_field_paths: &mut BTreeMap<(String, String), BTreeSet<String>>,
    safe_type_paths_by_producer: &mut BTreeMap<(String, String), BTreeSet<String>>,
    safe_field_paths_by_producer: &mut BTreeMap<(String, String, String), BTreeSet<String>>,
) {
    safe_type_paths.retain(|raw_type, _| !event_protocol_reserves_raw_type(raw_type));
    safe_field_paths.retain(|(raw_type, _), _| !event_protocol_reserves_raw_type(raw_type));
    safe_type_paths_by_producer
        .retain(|(_, raw_type), _| !event_protocol_reserves_raw_type(raw_type));
    safe_field_paths_by_producer
        .retain(|(_, raw_type, _), _| !event_protocol_reserves_raw_type(raw_type));
}

fn event_container_field_pair_is_exact(
    raw_type: &str,
    pointer_field: &str,
    count_field: &str,
) -> bool {
    EVENT_CONTAINER_FIELD_PAIRS
        .iter()
        .any(|candidate| candidate == &(raw_type, pointer_field, count_field))
}

fn event_container_fields_are_complete<'a>(
    relations: impl IntoIterator<Item = (&'a str, &'a str)>,
) -> bool {
    let expected = EVENT_CONTAINER_FIELD_PAIRS
        .iter()
        .flat_map(|(raw_type, pointer, count)| [(*raw_type, *pointer), (*raw_type, *count)])
        .collect::<BTreeSet<_>>();
    let actual = relations.into_iter().collect::<Vec<_>>();
    actual.len() == expected.len() && actual.into_iter().collect::<BTreeSet<_>>() == expected
}

#[derive(Clone, Debug, Eq, Ord, PartialEq, PartialOrd)]
struct SnapshotExposure {
    snapshot_capture_node: usize,
    slot_owner: String,
    slot_field: Option<String>,
    public_type: String,
    public_field: Option<String>,
}

#[derive(Clone, Copy)]
enum InvocationRef<'a> {
    Call(&'a ExprCall),
    Method(&'a ExprMethodCall),
}

struct InvocationResolution<'a> {
    target: usize,
    arguments: Vec<&'a Expr>,
    parameter_offset: usize,
}

fn collect_published_captures(
    builder: &IndexBuilder,
    resolved_owners: &[Option<String>],
    by_module_ident: &BTreeMap<(String, String), Vec<usize>>,
    by_owner_ident: &BTreeMap<(String, String), Vec<usize>>,
    publications: &BTreeSet<SnapshotPublication>,
    snapshot_slots: &BTreeSet<SnapshotSlotRelation>,
) -> BTreeSet<PublishedCapture> {
    let raw_captures = collect_complete_raw_snapshot_captures(builder);
    if raw_captures.len() != 1 || publications.len() != 1 {
        return BTreeSet::new();
    }
    let publication = publications.first().expect("one snapshot publication");
    let mut published = BTreeSet::new();
    for (bridge_node, node) in builder.nodes.iter().enumerate() {
        let Some(statements) = exact_enabled_statements(&node.body, &builder.coordinate) else {
            continue;
        };
        let [syn::Stmt::Expr(Expr::MethodCall(publish), Some(_))] = statements.as_slice() else {
            continue;
        };
        let Some(cache_binding) = direct_binding_name(&publish.receiver) else {
            continue;
        };
        let Some(cache_parameter) =
            signature_typed_parameter_index(&node.signature, &cache_binding)
        else {
            continue;
        };
        let Some(resolved) = resolve_invocation(
            builder,
            bridge_node,
            InvocationRef::Method(publish),
            resolved_owners,
            by_module_ident,
            by_owner_ident,
        ) else {
            continue;
        };
        if resolved.target != publication.publisher_node {
            continue;
        }
        let Some(argument_index) = publication
            .snapshot_parameter
            .checked_sub(resolved.parameter_offset)
        else {
            continue;
        };
        let Some(snapshot_expression) = resolved.arguments.get(argument_index) else {
            continue;
        };
        let Some(snapshot_invocation) = invocation_from_expression(snapshot_expression) else {
            continue;
        };
        let Some(snapshot_capture) = resolve_invocation(
            builder,
            bridge_node,
            snapshot_invocation,
            resolved_owners,
            by_module_ident,
            by_owner_ident,
        ) else {
            continue;
        };
        let relations = snapshot_slots
            .iter()
            .filter(|relation| {
                relation.snapshot_capture_node == snapshot_capture.target
                    && relation.snapshot_owner == publication.snapshot_owner
            })
            .collect::<Vec<_>>();
        if relations.len() != snapshot_slots.len() {
            continue;
        }
        let raw_snapshot_owners = relations
            .iter()
            .map(|relation| relation.raw_snapshot_owner.as_str())
            .collect::<BTreeSet<_>>();
        let raw_snapshot_parameters = relations
            .iter()
            .map(|relation| relation.raw_snapshot_parameter)
            .collect::<BTreeSet<_>>();
        if raw_snapshot_owners.len() != 1 || raw_snapshot_parameters.len() != 1 {
            continue;
        }
        let raw_snapshot_owner = raw_snapshot_owners
            .first()
            .copied()
            .expect("one raw snapshot owner");
        let raw_snapshot_parameter = *raw_snapshot_parameters
            .first()
            .expect("one raw snapshot parameter");
        let Some(raw_expression) = snapshot_capture.arguments.get(raw_snapshot_parameter) else {
            continue;
        };
        let Some(raw_invocation) = invocation_from_expression(raw_expression) else {
            continue;
        };
        let Some(raw_capture) = resolve_invocation(
            builder,
            bridge_node,
            raw_invocation,
            resolved_owners,
            by_module_ident,
            by_owner_ident,
        ) else {
            continue;
        };
        let Some(raw_proof) = raw_captures.get(&raw_capture.target) else {
            continue;
        };
        if raw_proof.owner != raw_snapshot_owner {
            continue;
        }
        let Some(world_expression) = raw_capture.arguments.get(raw_proof.world_parameter) else {
            continue;
        };
        let Some(world_binding) = direct_binding_name(world_expression) else {
            continue;
        };
        let Some(world_parameter) =
            signature_typed_parameter_index(&node.signature, &world_binding)
        else {
            continue;
        };
        let snapshot_brand_parameters = relations
            .iter()
            .map(|relation| relation.snapshot_brand_parameter)
            .collect::<BTreeSet<_>>();
        let Some(snapshot_brand_parameter) = (snapshot_brand_parameters.len() == 1)
            .then(|| snapshot_brand_parameters.first())
            .flatten()
        else {
            continue;
        };
        let Some((brand_parameter, brand_binding)) =
            parameter_binding_for_event_owner(builder, node, "IdBrand")
        else {
            continue;
        };
        if snapshot_capture
            .arguments
            .get(*snapshot_brand_parameter)
            .and_then(|argument| direct_binding_name(argument))
            .as_deref()
            != Some(&brand_binding)
        {
            continue;
        }
        let snapshot_epoch_parameters = relations
            .iter()
            .filter_map(|relation| relation.snapshot_epoch_parameter)
            .collect::<BTreeSet<_>>();
        let epoch_parameter = match snapshot_epoch_parameters.len() {
            0 => None,
            1 => {
                let snapshot_epoch_parameter = *snapshot_epoch_parameters
                    .first()
                    .expect("one snapshot epoch parameter");
                let Some((epoch_parameter, epoch_binding)) =
                    parameter_binding_for_event_owner(builder, node, "ContactEpoch")
                else {
                    continue;
                };
                if snapshot_capture
                    .arguments
                    .get(snapshot_epoch_parameter)
                    .and_then(|argument| direct_binding_name(argument))
                    .as_deref()
                    != Some(&epoch_binding)
                {
                    continue;
                }
                Some(epoch_parameter)
            }
            _ => continue,
        };
        published.insert(PublishedCapture {
            bridge_node,
            cache_parameter,
            world_parameter,
            brand_parameter,
            epoch_parameter,
            snapshot_capture_node: snapshot_capture.target,
            snapshot_owner: publication.snapshot_owner.clone(),
            accessor_node: publication.accessor_node,
        });
    }
    published
}

fn strict_expression(expression: &Expr) -> &Expr {
    match expression {
        Expr::Group(group) => strict_expression(&group.expr),
        Expr::Paren(paren) => strict_expression(&paren.expr),
        expression => expression,
    }
}

fn exact_self_member_chain(expression: &Expr, expected: &[&str]) -> bool {
    let mut expression = strict_expression(expression);
    let mut members = Vec::new();
    while let Expr::Field(field) = expression {
        let Some(member) = named_member(&field.member) else {
            return false;
        };
        members.push(member);
        expression = strict_expression(&field.base);
    }
    members.reverse();
    direct_binding_name(expression).as_deref() == Some("self")
        && members
            .iter()
            .map(String::as_str)
            .eq(expected.iter().copied())
}

fn exact_self_tuple_field(expression: &Expr, index: u32) -> bool {
    let Expr::Field(field) = strict_expression(expression) else {
        return false;
    };
    matches!(&field.member, syn::Member::Unnamed(member) if member.index == index)
        && direct_binding_name(&field.base).as_deref() == Some("self")
}

fn exact_immutable_reference_to_self_member(expression: &Expr, expected: &[&str]) -> bool {
    let Expr::Reference(reference) = strict_expression(expression) else {
        return false;
    };
    reference.mutability.is_none() && exact_self_member_chain(&reference.expr, expected)
}

fn exact_mut_reference_to_self_member(expression: &Expr, expected: &[&str]) -> bool {
    let Expr::Reference(reference) = strict_expression(expression) else {
        return false;
    };
    reference.mutability.is_some() && exact_self_member_chain(&reference.expr, expected)
}

fn exact_shared_zero_arg_accessor<'a>(node: &'a Node, builder: &IndexBuilder) -> Option<&'a Expr> {
    let [FnArg::Receiver(receiver)] = node.signature.inputs.iter().collect::<Vec<_>>().as_slice()
    else {
        return None;
    };
    if receiver.reference.is_none() || receiver.mutability.is_some() {
        return None;
    }
    let statements = exact_enabled_statements(&node.body, &builder.coordinate)?;
    let [syn::Stmt::Expr(tail, None)] = statements.as_slice() else {
        return None;
    };
    Some(strict_expression(tail))
}

fn exact_world_event_storage_contract(builder: &IndexBuilder, world_owner: &str) -> bool {
    match builder.crate_name.as_str() {
        "boxdd" => {
            owner_field_has_exact_standard_container(
                builder,
                world_owner,
                "core",
                &["std::rc::Rc", "alloc::rc::Rc"],
                &["core::world_core::WorldCore"],
            ) && owner_field_has_exact_standard_container(
                builder,
                world_owner,
                "events",
                &["std::rc::Rc", "alloc::rc::Rc"],
                &["events::EventCache"],
            )
        }
        "fixture" => true,
        _ => false,
    }
}

fn exact_world_core_brand_accessor(
    builder: &IndexBuilder,
    core_owner: &str,
    resolved_owners: &[Option<String>],
) -> Option<usize> {
    let candidates = builder
        .nodes
        .iter()
        .enumerate()
        .filter_map(|(node_index, node)| {
            (node.ident == "brand" && resolved_owners[node_index].as_deref() == Some(core_owner))
                .then_some(node_index)
        })
        .collect::<Vec<_>>();
    let [target] = candidates.as_slice() else {
        return None;
    };
    let node = &builder.nodes[*target];
    (node.return_type.as_ref().is_some_and(|return_type| {
        return_type.owned
            && return_type.wrappers.is_empty()
            && builder.resolve_type_ref(&return_type.value).as_deref() == Some("id::IdBrand")
    }) && owner_field_has_exact_type_syntax(builder, core_owner, "brand", "id::IdBrand")
        && exact_shared_zero_arg_accessor(node, builder)
            .is_some_and(|body| exact_self_member_chain(body, &["brand"])))
    .then_some(*target)
}

fn collect_world_event_access_contract(
    builder: &IndexBuilder,
    resolved_owners: &[Option<String>],
    by_module_ident: &BTreeMap<(String, String), Vec<usize>>,
    by_owner_ident: &BTreeMap<(String, String), Vec<usize>>,
) -> Option<WorldEventAccessContract> {
    let expected_public = format!("{}::World", builder.crate_name);
    let owners = builder
        .canonical_public_paths
        .iter()
        .filter_map(|(owner, public)| (public == &expected_public).then_some(owner.clone()))
        .collect::<Vec<_>>();
    let [world_owner] = owners.as_slice() else {
        return None;
    };
    let candidates = |ident: &str| {
        builder
            .nodes
            .iter()
            .enumerate()
            .filter_map(|(node_index, node)| {
                (node.ident == ident && resolved_owners[node_index].as_ref() == Some(world_owner))
                    .then_some(node_index)
            })
            .collect::<Vec<_>>()
    };
    let raw_candidates = candidates("raw");
    let core_candidates = candidates("core");
    let [core_accessor] = core_candidates.as_slice() else {
        return None;
    };
    let [raw_accessor] = raw_candidates.as_slice() else {
        return None;
    };
    let brand_candidates = candidates("brand");
    let [brand_accessor] = brand_candidates.as_slice() else {
        return None;
    };
    let cache_candidates = candidates("event_cache");
    let [cache_accessor] = cache_candidates.as_slice() else {
        return None;
    };
    let core_node = &builder.nodes[*core_accessor];
    let core_owner = core_node
        .return_type
        .as_ref()
        .and_then(|return_type| builder.resolve_type_ref(&return_type.value))?;
    let expected_core_owner = match builder.crate_name.as_str() {
        "boxdd" => "core::world_core::WorldCore",
        "fixture" => "Core",
        _ => return None,
    };
    let core_return_is_exact = core_node.return_type.as_ref().is_some_and(|return_type| {
        !return_type.owned
            && return_type.wrappers.is_empty()
            && builder.resolve_type_ref(&return_type.value).as_deref() == Some(expected_core_owner)
    });
    if core_owner != expected_core_owner
        || !core_return_is_exact
        || !exact_world_event_storage_contract(builder, world_owner)
        || !exact_shared_zero_arg_accessor(core_node, builder)
            .is_some_and(|body| matches!(strict_expression(body), Expr::Reference(reference) if reference.mutability.is_none() && exact_self_member_chain(&reference.expr, &["core"])))
    {
        return None;
    }
    if !exact_shared_zero_arg_accessor(&builder.nodes[*raw_accessor], builder)
        .is_some_and(|body| exact_self_member_chain(body, &["core", "id"]))
    {
        return None;
    }
    let core_brand_target = match builder.crate_name.as_str() {
        "boxdd" => exact_world_core_brand_accessor(builder, &core_owner, resolved_owners),
        "fixture" => None,
        _ => return None,
    };
    let exact_brand = match builder.crate_name.as_str() {
        "boxdd" => exact_shared_zero_arg_accessor(&builder.nodes[*brand_accessor], builder)
            .and_then(|body| {
                let Expr::Call(call) = strict_expression(body) else {
                    return None;
                };
                resolve_invocation(
                    builder,
                    *brand_accessor,
                    InvocationRef::Call(call),
                    resolved_owners,
                    by_module_ident,
                    by_owner_ident,
                )
                .filter(|resolved| {
                    resolved.parameter_offset == 0
                        && resolved.arguments.len() == 1
                        && core_brand_target.is_some_and(|target| resolved.target == target)
                        && exact_immutable_reference_to_self_member(
                            resolved.arguments[0],
                            &["core"],
                        )
                })
            })
            .is_some(),
        "fixture" => exact_shared_zero_arg_accessor(&builder.nodes[*brand_accessor], builder)
            .is_some_and(|body| {
                let Expr::MethodCall(call) = body else {
                    return false;
                };
                call.method == "brand"
                    && call.args.is_empty()
                    && exact_self_member_chain(&call.receiver, &["core"])
            }),
        _ => false,
    };
    let core_brand_is_exact = match builder.crate_name.as_str() {
        "boxdd" => {
            builder.nodes[*brand_accessor]
                .return_type
                .as_ref()
                .is_some_and(|return_type| {
                    return_type.owned
                        && return_type.wrappers.is_empty()
                        && builder.resolve_type_ref(&return_type.value).as_deref()
                            == Some("id::IdBrand")
                })
                && core_brand_target.is_some()
        }
        "fixture" => true,
        _ => false,
    };
    if !exact_brand || !core_brand_is_exact {
        return None;
    }
    let exact_cache = exact_shared_zero_arg_accessor(&builder.nodes[*cache_accessor], builder)
        .is_some_and(|body| {
            let Expr::Reference(reference) = body else {
                return false;
            };
            reference.mutability.is_none() && exact_self_member_chain(&reference.expr, &["events"])
        });
    let cache_return_is_exact = match builder.crate_name.as_str() {
        "boxdd" => builder.nodes[*cache_accessor]
            .return_type
            .as_ref()
            .is_some_and(|return_type| {
                !return_type.owned
                    && return_type.wrappers.is_empty()
                    && builder.resolve_type_ref(&return_type.value).as_deref()
                        == Some("events::EventCache")
            }),
        "fixture" => true,
        _ => false,
    };
    if !exact_cache || !cache_return_is_exact {
        return None;
    }
    Some(WorldEventAccessContract {
        world_owner: world_owner.clone(),
        core_owner,
        raw_accessor: *raw_accessor,
        brand_accessor: *brand_accessor,
        cache_accessor: *cache_accessor,
    })
}

#[allow(clippy::too_many_arguments)]
fn exact_direct_self_accessor_call(
    builder: &IndexBuilder,
    context_node: usize,
    expression: &Expr,
    accessor_node: usize,
    resolved_owners: &[Option<String>],
    by_module_ident: &BTreeMap<(String, String), Vec<usize>>,
    by_owner_ident: &BTreeMap<(String, String), Vec<usize>>,
) -> bool {
    let Expr::MethodCall(call) = strict_expression(expression) else {
        return false;
    };
    if !call.args.is_empty() || direct_binding_name(&call.receiver).as_deref() != Some("self") {
        return false;
    }
    resolve_invocation(
        builder,
        context_node,
        InvocationRef::Method(call),
        resolved_owners,
        by_module_ident,
        by_owner_ident,
    )
    .is_some_and(|resolved| resolved.target == accessor_node && resolved.parameter_offset == 1)
}

fn exact_result_variant_pattern(pattern: &Pat, variant: &str) -> Option<String> {
    let Pat::TupleStruct(pattern) = pattern else {
        return None;
    };
    if pattern.path.leading_colon.is_some() || path_segments(&pattern.path).as_slice() != [variant]
    {
        return None;
    }
    let values = pattern.elems.iter().collect::<Vec<_>>();
    let [value] = values.as_slice() else {
        return None;
    };
    simple_pattern_ident(value)
}

fn exact_canonical_standard_variant_path(
    _builder: &IndexBuilder,
    node: &Node,
    path: &syn::Path,
    namespace: &str,
    enum_name: &str,
    variant: &str,
) -> bool {
    let segments = path_segments(path);
    matches!(
        segments.as_slice(),
        [root, actual_namespace, actual_enum, actual_variant]
            if matches!(root.as_str(), "core" | "std")
                && actual_namespace == namespace
                && actual_enum == enum_name
                && actual_variant == variant
    ) && path.leading_colon.is_some()
        && path_is_unshadowed_for_node(node, path)
}

fn exact_canonical_result_variant_pattern(
    builder: &IndexBuilder,
    node: &Node,
    pattern: &Pat,
    variant: &str,
) -> Option<String> {
    let Pat::TupleStruct(pattern) = pattern else {
        return None;
    };
    if pattern.qself.is_some()
        || !exact_canonical_standard_variant_path(
            builder,
            node,
            &pattern.path,
            "result",
            "Result",
            variant,
        )
    {
        return None;
    }
    let values = pattern.elems.iter().collect::<Vec<_>>();
    let [value] = values.as_slice() else {
        return None;
    };
    simple_pattern_ident(value)
}

fn exact_canonical_option_some_pattern(
    builder: &IndexBuilder,
    node: &Node,
    pattern: &Pat,
) -> Option<String> {
    let Pat::TupleStruct(pattern) = pattern else {
        return None;
    };
    if pattern.qself.is_some()
        || !exact_canonical_standard_variant_path(
            builder,
            node,
            &pattern.path,
            "option",
            "Option",
            "Some",
        )
    {
        return None;
    }
    let values = pattern.elems.iter().collect::<Vec<_>>();
    let [value] = values.as_slice() else {
        return None;
    };
    simple_pattern_ident(value)
}

fn exact_canonical_option_none_pattern(builder: &IndexBuilder, node: &Node, pattern: &Pat) -> bool {
    let Pat::Path(pattern) = pattern else {
        return false;
    };
    pattern.qself.is_none()
        && exact_canonical_standard_variant_path(
            builder,
            node,
            &pattern.path,
            "option",
            "Option",
            "None",
        )
}

fn exact_canonical_option_none_expression(
    builder: &IndexBuilder,
    node: &Node,
    expression: &Expr,
) -> bool {
    let Expr::Path(none) = strict_expression(expression) else {
        return false;
    };
    none.qself.is_none()
        && exact_canonical_standard_variant_path(
            builder, node, &none.path, "option", "Option", "None",
        )
}

fn exact_canonical_option_some_call(
    builder: &IndexBuilder,
    node: &Node,
    expression: &Expr,
) -> bool {
    let Expr::Call(some) = strict_expression(expression) else {
        return false;
    };
    let Expr::Path(function) = strict_expression(&some.func) else {
        return false;
    };
    function.qself.is_none()
        && some.args.len() == 1
        && exact_canonical_standard_variant_path(
            builder,
            node,
            &function.path,
            "option",
            "Option",
            "Some",
        )
}

fn exact_result_success_binding(
    builder: &IndexBuilder,
    module: &str,
    expression: &Expr,
    binding: &str,
) -> bool {
    let Expr::Call(result) = strict_expression(expression) else {
        return false;
    };
    let Expr::Path(constructor) = strict_expression(&result.func) else {
        return false;
    };
    result.args.len() == 1
        && constructor.qself.is_none()
        && builder.result_ok_constructor_is_proven(module, &path_segments(&constructor.path))
        && direct_binding_name(&result.args[0]).as_deref() == Some(binding)
}

fn exact_result_error_binding(
    builder: &IndexBuilder,
    module: &str,
    expression: &Expr,
    binding: &str,
) -> bool {
    let Expr::Call(result) = strict_expression(expression) else {
        return false;
    };
    let Expr::Path(constructor) = strict_expression(&result.func) else {
        return false;
    };
    result.args.len() == 1
        && constructor.qself.is_none()
        && builder.result_err_constructor_is_proven(module, &path_segments(&constructor.path))
        && direct_binding_name(&result.args[0]).as_deref() == Some(binding)
}

fn exact_contact_epoch_checked_next(
    builder: &IndexBuilder,
    resolved_owners: &[Option<String>],
    by_owner_ident: &BTreeMap<(String, String), Vec<usize>>,
) -> bool {
    let Some(candidates) =
        by_owner_ident.get(&("id::ContactEpoch".to_owned(), "checked_next".to_owned()))
    else {
        return false;
    };
    let [target_index] = candidates.as_slice() else {
        return false;
    };
    let target = &builder.nodes[*target_index];
    let [FnArg::Receiver(receiver)] = target
        .signature
        .inputs
        .iter()
        .collect::<Vec<_>>()
        .as_slice()
    else {
        return false;
    };
    let Some(statements) = exact_enabled_statements(&target.body, &builder.coordinate) else {
        return false;
    };
    let [syn::Stmt::Expr(expression, _)] = statements.as_slice() else {
        return false;
    };
    let Expr::MethodCall(ok_or) = strict_expression(expression) else {
        return false;
    };
    let Expr::MethodCall(map) = strict_expression(&ok_or.receiver) else {
        return false;
    };
    let Expr::MethodCall(checked_add) = strict_expression(&map.receiver) else {
        return false;
    };
    let Some(mapper) = map.args.first().map(strict_expression) else {
        return false;
    };
    let Expr::Path(mapper) = mapper else {
        return false;
    };
    resolved_owners[*target_index].as_deref() == Some("id::ContactEpoch")
        && receiver.reference.is_none()
        && receiver.mutability.is_none()
        && node_returns_standard_result(builder, target)
        && target.return_type.as_ref().is_some_and(|return_type| {
            return_type.owned
                && return_type.wrappers.len() == 1
                && return_type.value.module == "id"
                && return_type.value.segments.as_slice() == ["ContactEpoch"]
        })
        && owner_field_has_exact_primitive_type(builder, "id::ContactEpoch", "0", "u64")
        && ok_or.method == "ok_or"
        && ok_or.args.len() == 1
        && expression_resolves_exactly(
            builder,
            &target.module,
            &ok_or.args[0],
            "error::ApiError::ObjectIdentityExhausted",
        )
        && map.method == "map"
        && map.args.len() == 1
        && mapper.qself.is_none()
        && path_segments(&mapper.path).as_slice() == ["Self"]
        && checked_add.method == "checked_add"
        && checked_add.args.len() == 1
        && exact_self_tuple_field(&checked_add.receiver, 0)
        && matches!(checked_add.args.first(), Some(argument) if matches!(strict_expression(argument), Expr::Lit(literal) if matches!(&literal.lit, syn::Lit::Int(value) if value.base10_parse::<u64>().ok() == Some(1))))
}

fn exact_world_core_poison(
    builder: &IndexBuilder,
    target_index: usize,
    core_owner: &str,
    resolved_owners: &[Option<String>],
) -> bool {
    let target = &builder.nodes[target_index];
    let [FnArg::Receiver(receiver)] = target
        .signature
        .inputs
        .iter()
        .collect::<Vec<_>>()
        .as_slice()
    else {
        return false;
    };
    let Some(statements) = exact_enabled_statements(&target.body, &builder.coordinate) else {
        return false;
    };
    let [syn::Stmt::Expr(expression, _)] = statements.as_slice() else {
        return false;
    };
    let Expr::If(transition) = strict_expression(expression) else {
        return false;
    };
    let Expr::Binary(live_check) = strict_expression(&transition.cond) else {
        return false;
    };
    let Some(get) = exact_standard_function_call(
        builder,
        &target.module,
        &live_check.left,
        "std::cell::Cell::get",
    ) else {
        return false;
    };
    let Some(transition_statements) =
        exact_enabled_statements(&transition.then_branch, &builder.coordinate)
    else {
        return false;
    };
    let [syn::Stmt::Expr(set_expression, Some(_))] = transition_statements.as_slice() else {
        return false;
    };
    let Some(set) = exact_standard_function_call(
        builder,
        &target.module,
        set_expression,
        "std::cell::Cell::set",
    ) else {
        return false;
    };
    let Some((core_module, _)) = core_owner.rsplit_once("::") else {
        return false;
    };
    let lifecycle_owner = format!("{core_module}::LifecycleState");
    let owner_is_exact = resolved_owners[target_index].as_deref() == Some(core_owner);
    let receiver_is_exact = receiver.reference.is_some() && receiver.mutability.is_none();
    let storage_is_exact = owner_field_has_exact_standard_container(
        builder,
        core_owner,
        "lifecycle",
        &["std::cell::Cell"],
        &[lifecycle_owner.as_str()],
    );
    let condition_is_exact = transition.else_branch.is_none()
        && matches!(live_check.op, syn::BinOp::Eq(_))
        && get.args.len() == 1
        && exact_immutable_reference_to_self_member(&get.args[0], &["lifecycle"])
        && expression_resolves_exactly(
            builder,
            &target.module,
            &live_check.right,
            &format!("{lifecycle_owner}::Live"),
        );
    let transition_is_exact = set.args.len() == 2
        && exact_immutable_reference_to_self_member(&set.args[0], &["lifecycle"])
        && expression_resolves_exactly(
            builder,
            &target.module,
            &set.args[1],
            &format!("{lifecycle_owner}::Poisoned"),
        );
    owner_is_exact
        && target.ident == "poison"
        && receiver_is_exact
        && storage_is_exact
        && condition_is_exact
        && transition_is_exact
}

fn exact_world_core_advance_contact_epoch(
    builder: &IndexBuilder,
    target_index: usize,
    core_owner: &str,
    resolved_owners: &[Option<String>],
    by_module_ident: &BTreeMap<(String, String), Vec<usize>>,
    by_owner_ident: &BTreeMap<(String, String), Vec<usize>>,
) -> bool {
    let target = &builder.nodes[target_index];
    let [FnArg::Receiver(receiver)] = target
        .signature
        .inputs
        .iter()
        .collect::<Vec<_>>()
        .as_slice()
    else {
        return false;
    };
    let Some(statements) = exact_enabled_statements(&target.body, &builder.coordinate) else {
        return false;
    };
    let [next, set, syn::Stmt::Expr(success, None)] = statements.as_slice() else {
        return false;
    };
    let Some((next_binding, next_expression)) = exact_local_binding(next) else {
        return false;
    };
    let Expr::Match(next_match) = strict_expression(next_expression) else {
        return false;
    };
    let Expr::MethodCall(checked_next) = strict_expression(&next_match.expr) else {
        return false;
    };
    let Expr::MethodCall(contact_epoch) = strict_expression(&checked_next.receiver) else {
        return false;
    };
    let [ok_arm, error_arm] = next_match.arms.as_slice() else {
        return false;
    };
    let Some(ok_binding) = exact_result_variant_pattern(&ok_arm.pat, "Ok") else {
        return false;
    };
    let Some(error_binding) = exact_result_variant_pattern(&error_arm.pat, "Err") else {
        return false;
    };
    let Expr::Block(error_block) = strict_expression(&error_arm.body) else {
        return false;
    };
    let Some(error_statements) = exact_enabled_statements(&error_block.block, &builder.coordinate)
    else {
        return false;
    };
    let [
        syn::Stmt::Expr(poison, Some(_)),
        syn::Stmt::Expr(returned, Some(_)),
    ] = error_statements.as_slice()
    else {
        return false;
    };
    let Expr::Call(poison) = strict_expression(poison) else {
        return false;
    };
    let Expr::Return(returned) = strict_expression(returned) else {
        return false;
    };
    let Some(returned) = returned.expr.as_deref() else {
        return false;
    };
    let Some(set_expression) = statement_expression(set) else {
        return false;
    };
    let Expr::MethodCall(set) = strict_expression(set_expression) else {
        return false;
    };
    let owner_is_exact = resolved_owners[target_index].as_deref() == Some(core_owner);
    let receiver_is_exact = receiver.reference.is_some() && receiver.mutability.is_none();
    let result_is_exact = node_returns_standard_result(builder, target)
        && target.return_type.as_ref().is_some_and(|return_type| {
            return_type.owned
                && return_type.wrappers.len() == 1
                && builder.resolve_type_ref(&return_type.value).as_deref()
                    == Some("id::ContactEpoch")
        });
    let storage_is_exact = owner_field_has_exact_standard_container(
        builder,
        core_owner,
        "contact_epoch",
        &["std::cell::Cell"],
        &["id::ContactEpoch"],
    );
    let next_is_exact = checked_next.method == "checked_next"
        && checked_next.args.is_empty()
        && contact_epoch.method == "get"
        && contact_epoch.args.is_empty()
        && exact_self_member_chain(&contact_epoch.receiver, &["contact_epoch"]);
    let ok_arm_is_exact = ok_arm.guard.is_none()
        && direct_binding_name(&ok_arm.body).as_deref() == Some(next_binding.as_str())
        && ok_binding == next_binding;
    let poison_target = by_owner_ident
        .get(&(core_owner.to_owned(), "poison".to_owned()))
        .and_then(|candidates| match candidates.as_slice() {
            [target] => Some(*target),
            _ => None,
        });
    let poison_resolution = resolve_invocation(
        builder,
        target_index,
        InvocationRef::Call(poison),
        resolved_owners,
        by_module_ident,
        by_owner_ident,
    );
    let error_arm_is_exact = error_arm.guard.is_none()
        && poison_target.is_some_and(|poison_target| {
            poison_resolution.as_ref().is_some_and(|resolved| {
                resolved.target == poison_target
                    && resolved.parameter_offset == 0
                    && resolved.arguments.len() == 1
                    && direct_binding_name(resolved.arguments[0]).as_deref() == Some("self")
                    && exact_world_core_poison(builder, poison_target, core_owner, resolved_owners)
            })
        })
        && exact_result_error_binding(builder, &target.module, returned, &error_binding);
    let set_is_exact = set.method == "set"
        && set.args.len() == 1
        && exact_self_member_chain(&set.receiver, &["contact_epoch"])
        && direct_binding_name(&set.args[0]).as_deref() == Some(next_binding.as_str());
    let success_is_exact =
        exact_result_success_binding(builder, &target.module, success, &next_binding);
    let checked_next_is_exact =
        exact_contact_epoch_checked_next(builder, resolved_owners, by_owner_ident);
    owner_is_exact
        && receiver_is_exact
        && result_is_exact
        && storage_is_exact
        && next_is_exact
        && ok_arm_is_exact
        && error_arm_is_exact
        && set_is_exact
        && success_is_exact
        && checked_next_is_exact
}

fn exact_contact_epoch_origin(
    builder: &IndexBuilder,
    context_node: usize,
    expression: &Expr,
    access: &WorldEventAccessContract,
    resolved_owners: &[Option<String>],
    by_module_ident: &BTreeMap<(String, String), Vec<usize>>,
    by_owner_ident: &BTreeMap<(String, String), Vec<usize>>,
) -> bool {
    let Expr::Try(try_expression) = strict_expression(expression) else {
        return false;
    };
    let Some(candidates) = by_owner_ident.get(&(
        access.core_owner.clone(),
        "advance_contact_epoch".to_owned(),
    )) else {
        return false;
    };
    let [target] = candidates.as_slice() else {
        return false;
    };
    match builder.crate_name.as_str() {
        "boxdd" => {
            let Expr::Call(call) = strict_expression(&try_expression.expr) else {
                return false;
            };
            resolve_invocation(
                builder,
                context_node,
                InvocationRef::Call(call),
                resolved_owners,
                by_module_ident,
                by_owner_ident,
            )
            .is_some_and(|resolved| {
                resolved.target == *target
                    && resolved.parameter_offset == 0
                    && resolved.arguments.len() == 1
                    && exact_immutable_reference_to_self_member(resolved.arguments[0], &["core"])
                    && exact_world_core_advance_contact_epoch(
                        builder,
                        *target,
                        &access.core_owner,
                        resolved_owners,
                        by_module_ident,
                        by_owner_ident,
                    )
            })
        }
        "fixture" => {
            let Expr::MethodCall(call) = strict_expression(&try_expression.expr) else {
                return false;
            };
            call.method == "advance_contact_epoch"
                && call.args.is_empty()
                && exact_self_member_chain(&call.receiver, &["core"])
                && builder.nodes[*target].ident == "advance_contact_epoch"
                && resolved_owners[*target].as_ref() == Some(&access.core_owner)
        }
        _ => false,
    }
}

