    fn assert_event_protocol(index: &RustIndex, expected: bool, case: &str) {
        for producer in ["fixture::World::step", "fixture::World::try_step"] {
            for &(raw_type, public_path) in EVENT_OUTER_TYPE_ROWS {
                assert_eq!(
                    index.path_has_safe_ffi_type_witness_from(producer, public_path, raw_type),
                    expected,
                    "{case}: `{producer}` event type `{raw_type}` -> `{public_path}`"
                );
            }
            for &(raw_type, raw_field, public_path) in EVENT_OUTER_FIELD_ROWS {
                assert_eq!(
                    index.path_has_safe_ffi_field_witness_from(
                        producer,
                        public_path,
                        raw_type,
                        raw_field,
                    ),
                    expected,
                    "{case}: `{producer}` event field `{raw_type}::{raw_field}` -> `{public_path}`"
                );
            }
            for &(raw_type, raw_field, public_path) in EVENT_INNER_FIELD_ROWS {
                assert_eq!(
                    index.path_has_safe_ffi_field_witness_from(
                        producer,
                        public_path,
                        raw_type,
                        raw_field,
                    ),
                    expected,
                    "{case}: `{producer}` inner event field `{raw_type}::{raw_field}` -> `{public_path}`"
                );
            }
        }
    }

    fn mutate_event_fixture(case: &str, edits: &[(&str, &str)]) -> String {
        edits.iter().fold(
            EVENT_PROTOCOL_FIXTURE.to_owned(),
            |current, &(before, after)| {
                assert_eq!(
                    current.matches(before).count(),
                    1,
                    "{case}: mutation anchor must be unique: {before}"
                );
                current.replacen(before, after, 1)
            },
        )
    }

    #[test]
    fn canonical_event_protocol_proves_all_rows() {
        let index =
            checked_event_protocol_fixture("event-protocol-canonical", EVENT_PROTOCOL_FIXTURE);
        assert_event_protocol(&index, true, "canonical");
    }

