    #[test]
    fn identity_storage_contract_rejects_proxy_types_and_lost_raw_identity() {
        assert!(identity_storage_contract_is_proven(
            "identity-storage-canonical",
            IDENTITY_STORAGE_CONTRACT_FIXTURE,
        ));

        let proxy_mutex = IDENTITY_STORAGE_CONTRACT_FIXTURE.replace(
            "state: Mutex<IdentityState>",
            "state: CertifiedMutex<IdentityState>",
        );
        assert!(!identity_storage_contract_is_proven(
            "identity-storage-proxy-mutex",
            &proxy_mutex,
        ));

        let proxy_brand =
            IDENTITY_STORAGE_CONTRACT_FIXTURE.replace("brand: IdBrand", "brand: BrandProxy");
        assert!(!identity_storage_contract_is_proven(
            "identity-storage-proxy-brand",
            &proxy_brand,
        ));

        let proxy_map = IDENTITY_STORAGE_CONTRACT_FIXTURE.replace(
            "bodies: HashMap<RawKey, BodyRegistration>",
            "bodies: CertifiedMap<RawKey, BodyRegistration>",
        );
        assert!(!identity_storage_contract_is_proven(
            "identity-storage-proxy-map",
            &proxy_map,
        ));

        let lost_generation = IDENTITY_STORAGE_CONTRACT_FIXTURE.replace(
            "Self::new(raw.index1, raw.generation)",
            "Self::new(raw.index1, 0)",
        );
        assert!(!identity_storage_contract_is_proven(
            "identity-storage-lost-generation",
            &lost_generation,
        ));

        let forged_nonce = IDENTITY_STORAGE_CONTRACT_FIXTURE.replace(
            "struct BodyRegistration { nonce: RegistrationNonce }",
            "struct BodyRegistration { nonce: u64 }",
        );
        assert!(!identity_storage_contract_is_proven(
            "identity-storage-forged-nonce",
            &forged_nonce,
        ));

        let constant_nonce_constructor = IDENTITY_STORAGE_CONTRACT_FIXTURE.replace(
            "NonZeroU64::new(value).map(Self).ok_or(ApiError::ObjectIdentityExhausted)",
            "NonZeroU64::new(1).map(Self).ok_or(ApiError::ObjectIdentityExhausted)",
        );
        assert!(!identity_storage_contract_is_proven(
            "identity-storage-constant-nonce-constructor",
            &constant_nonce_constructor,
        ));

        let wrapping_nonce_range =
            IDENTITY_STORAGE_CONTRACT_FIXTURE.replace("last.checked_add(count)", "Some(1)");
        assert!(!identity_storage_contract_is_proven(
            "identity-storage-wrapping-nonce-range",
            &wrapping_nonce_range,
        ));

        let constant_scalar_nonce = IDENTITY_STORAGE_CONTRACT_FIXTURE.replace(
            "RegistrationNonce::new(previous + 1)",
            "RegistrationNonce::new(1)",
        );
        assert!(!identity_storage_contract_is_proven(
            "identity-storage-constant-scalar-nonce",
            &constant_scalar_nonce,
        ));

        let wrong_lock = IDENTITY_STORAGE_CONTRACT_FIXTURE.replace(
            "self.state\n                            .lock()",
            "self.spare\n                            .lock()",
        );
        assert!(!identity_storage_contract_is_proven(
            "identity-storage-wrong-lock",
            &wrong_lock,
        ));

        let wrong_key_equivalence = IDENTITY_STORAGE_CONTRACT_FIXTURE
            .replace(
                "#[derive(PartialEq, Eq, Hash)]\n                pub struct RawKey",
                "pub struct RawKey",
            )
            .replace(
                "                impl RawKey {",
                "                impl PartialEq for RawKey {\n                    fn eq(&self, other: &Self) -> bool { self.index1 == other.index1 }\n                }\n                impl Eq for RawKey {}\n                impl std::hash::Hash for RawKey {\n                    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {\n                        std::hash::Hasher::write_i32(state, self.index1);\n                    }\n                }\n\n                impl RawKey {",
            );
        assert!(!identity_storage_contract_is_proven(
            "identity-storage-wrong-key-equivalence",
            &wrong_key_equivalence,
        ));
    }

    const PRODUCTION_IDENTITY_RESOLVER_FIXTURE: &str = r#"
        use std::rc::Rc;

        mod error {
            pub enum ApiError {
                InvalidBodyId,
                InvalidShapeId,
                InvalidJointId,
                InvalidChainId,
                ObjectIdentityExhausted,
                WrongWorld,
            }

            pub type ApiResult<T> = Result<T, ApiError>;
        }

        mod id {
            use core::num::NonZeroU64;

            use boxdd_sys::ffi;
            use crate::error::{ApiError, ApiResult};

            #[derive(Copy, Clone, PartialEq, Eq, Hash)]
            pub struct WorldToken(pub u64);

            #[derive(Copy, Clone, PartialEq, Eq, Hash, PartialOrd, Ord)]
            pub struct RegistrationNonce(NonZeroU64);

            impl RegistrationNonce {
                pub fn new(value: u64) -> ApiResult<Self> {
                    NonZeroU64::new(value).map(Self).ok_or(ApiError::ObjectIdentityExhausted)
                }
            }

            #[derive(Copy, Clone, PartialEq, Eq, Hash)]
            pub struct IdBrand {
                token: WorldToken,
                world0: u16,
                world_generation: u16,
            }

            pub struct BodyId { index1: i32, generation: u16, brand: IdBrand, registration_nonce: RegistrationNonce }
            pub struct ShapeId { index1: i32, generation: u16, brand: IdBrand, registration_nonce: RegistrationNonce }
            pub struct JointId { index1: i32, generation: u16, brand: IdBrand, registration_nonce: RegistrationNonce }
            pub struct ChainId { index1: i32, generation: u16, brand: IdBrand, registration_nonce: RegistrationNonce }

            impl IdBrand {
                pub fn token(self) -> WorldToken { self.token }

                pub fn body(self, raw: ffi::b2BodyId, registration_nonce: RegistrationNonce) -> BodyId {
                    BodyId { index1: raw.index1, generation: raw.generation, brand: self, registration_nonce }
                }
                pub fn shape(self, raw: ffi::b2ShapeId, registration_nonce: RegistrationNonce) -> ShapeId {
                    ShapeId { index1: raw.index1, generation: raw.generation, brand: self, registration_nonce }
                }
                pub fn joint(self, raw: ffi::b2JointId, registration_nonce: RegistrationNonce) -> JointId {
                    JointId { index1: raw.index1, generation: raw.generation, brand: self, registration_nonce }
                }
                pub fn chain(self, raw: ffi::b2ChainId, registration_nonce: RegistrationNonce) -> ChainId {
                    ChainId { index1: raw.index1, generation: raw.generation, brand: self, registration_nonce }
                }

                pub fn check_body_raw(self, raw: ffi::b2BodyId) -> ApiResult<()> {
                    if raw.index1 <= 0 { Err(ApiError::InvalidBodyId) } else if raw.world0 != self.world0 { Err(ApiError::WrongWorld) } else { Ok(()) }
                }
                pub fn check_shape_raw(self, raw: ffi::b2ShapeId) -> ApiResult<()> {
                    if raw.index1 <= 0 { Err(ApiError::InvalidShapeId) } else if raw.world0 != self.world0 { Err(ApiError::WrongWorld) } else { Ok(()) }
                }
                pub fn check_joint_raw(self, raw: ffi::b2JointId) -> ApiResult<()> {
                    if raw.index1 <= 0 { Err(ApiError::InvalidJointId) } else if raw.world0 != self.world0 { Err(ApiError::WrongWorld) } else { Ok(()) }
                }
                pub fn check_chain_raw(self, raw: ffi::b2ChainId) -> ApiResult<()> {
                    if raw.index1 <= 0 { Err(ApiError::InvalidChainId) } else if raw.world0 != self.world0 { Err(ApiError::WrongWorld) } else { Ok(()) }
                }
            }
        }

        mod core {
            pub mod identity_registry {
                use std::collections::HashMap;
                use std::sync::atomic::{AtomicU64, Ordering};
                use std::sync::{Arc, Mutex, OnceLock, Weak};

                use boxdd_sys::ffi;
                use crate::error::{ApiError, ApiResult};
                use crate::id::{BodyId, ChainId, IdBrand, JointId, RegistrationNonce, ShapeId, WorldToken};

                static REGISTRIES: OnceLock<Mutex<HashMap<WorldToken, Weak<ActiveIdentityRegistry>>>> = OnceLock::new();

                #[derive(PartialEq, Eq, Hash)]
                pub struct RawKey { index1: i32, generation: u16 }

                impl RawKey {
                    fn new(index1: i32, generation: u16) -> Self { Self { index1, generation } }
                }

                impl From<ffi::b2BodyId> for RawKey { fn from(raw: ffi::b2BodyId) -> Self { Self::new(raw.index1, raw.generation) } }
                impl From<ffi::b2ShapeId> for RawKey { fn from(raw: ffi::b2ShapeId) -> Self { Self::new(raw.index1, raw.generation) } }
                impl From<ffi::b2JointId> for RawKey { fn from(raw: ffi::b2JointId) -> Self { Self::new(raw.index1, raw.generation) } }
                impl From<ffi::b2ChainId> for RawKey { fn from(raw: ffi::b2ChainId) -> Self { Self::new(raw.index1, raw.generation) } }

                struct BodyRegistration { nonce: RegistrationNonce }
                struct ShapeRegistration { nonce: RegistrationNonce }
                struct JointRegistration { nonce: RegistrationNonce }
                struct ChainRegistration { nonce: RegistrationNonce }

                struct IdentityState {
                    bodies: HashMap<RawKey, BodyRegistration>,
                    shapes: HashMap<RawKey, ShapeRegistration>,
                    joints: HashMap<RawKey, JointRegistration>,
                    chains: HashMap<RawKey, ChainRegistration>,
                    retired_bodies: HashMap<RawKey, RegistrationNonce>,
                    retired_shapes: HashMap<RawKey, RegistrationNonce>,
                    retired_joints: HashMap<RawKey, RegistrationNonce>,
                    retired_chains: HashMap<RawKey, RegistrationNonce>,
                }

                pub struct ActiveIdentityRegistry {
                    brand: IdBrand,
                    last_nonce: AtomicU64,
                    state: Mutex<IdentityState>,
                }

                impl ActiveIdentityRegistry {
                    fn reserve_nonce_range(&self, count: u64) -> ApiResult<u64> {
                        debug_assert!(count > 0);
                        self.last_nonce
                            .fetch_update(Ordering::Relaxed, Ordering::Relaxed, |last| {
                                last.checked_add(count)
                            })
                            .map_err(|_| ApiError::ObjectIdentityExhausted)
                    }

                    fn allocate_nonce(&self) -> ApiResult<RegistrationNonce> {
                        let previous = self.reserve_nonce_range(1)?;
                        RegistrationNonce::new(previous + 1)
                    }

                    fn lock_state(&self) -> std::sync::MutexGuard<'_, IdentityState> {
                        self.state.lock().unwrap_or_else(|poisoned| poisoned.into_inner())
                    }

                    fn resolve_body_output(&self, raw: ffi::b2BodyId) -> ApiResult<BodyId> {
                        self.brand.check_body_raw(raw)?;
                        let state = self.lock_state();
                        let key = RawKey::from(raw);
                        let nonce = state
                            .bodies
                            .get(&key)
                            .map(|entry| entry.nonce)
                            .or_else(|| state.retired_bodies.get(&key).copied())
                            .ok_or(ApiError::InvalidBodyId)?;
                        std::mem::drop(state);
                        Ok(self.brand.body(raw, nonce))
                    }

                    pub(crate) fn clear_retired_outputs(&self) {
                        let mut state = self.lock_state();
                        state.retired_bodies.clear();
                        state.retired_shapes.clear();
                        state.retired_joints.clear();
                        state.retired_chains.clear();
                    }
                }

                fn lookup(brand: IdBrand) -> Option<Arc<ActiveIdentityRegistry>> {
                    let registries = REGISTRIES.get()?;
                    let registry = registries
                        .lock()
                        .unwrap_or_else(|poisoned| poisoned.into_inner())
                        .get(&brand.token())
                        .and_then(std::sync::Weak::upgrade)?;
                    (registry.brand == brand).then_some(registry)
                }

                pub fn resolve_body_for_brand(brand: IdBrand, raw: ffi::b2BodyId) -> ApiResult<BodyId> {
                    brand.check_body_raw(raw)?;
                    let registry = lookup(brand).ok_or(ApiError::InvalidBodyId)?;
                    ActiveIdentityRegistry::resolve_body_output(&registry, raw)
                }
            }

            pub mod world_core {
                use std::sync::Arc;

                use super::identity_registry::ActiveIdentityRegistry;

                pub struct WorldCore {
                    identities: Arc<ActiveIdentityRegistry>,
                }

                impl WorldCore {
                    pub(crate) fn clear_retired_identity_outputs(&self) {
                        ActiveIdentityRegistry::clear_retired_outputs(&self.identities);
                    }
                }
            }
        }

        pub struct World {
            core: Rc<core::world_core::WorldCore>,
        }

        impl World {
            pub(crate) fn clear_retired_identity_outputs(&self) {
                core::world_core::WorldCore::clear_retired_identity_outputs(&self.core);
            }
        }
    "#;

    fn production_identity_resolver_is_proven(name: &str, source: &str) -> bool {
        let root = fixture_root(name);
        fs::create_dir_all(&root).expect("production identity fixture root");
        let dependency_root = root.join("native");
        fs::create_dir_all(&dependency_root).expect("production identity dependency root");
        fs::write(
            dependency_root.join("Cargo.toml"),
            "[package]\nname = \"boxdd-sys\"\nversion = \"0.0.0\"\nedition = \"2024\"\n\n[lib]\npath = \"lib.rs\"\n",
        )
        .expect("production identity dependency manifest");
        fs::write(
            dependency_root.join("lib.rs"),
            r#"
                pub mod ffi {
                    #[derive(Clone, Copy)] pub struct b2BodyId { pub index1: i32, pub world0: u16, pub generation: u16 }
                    #[derive(Clone, Copy)] pub struct b2ShapeId { pub index1: i32, pub world0: u16, pub generation: u16 }
                    #[derive(Clone, Copy)] pub struct b2JointId { pub index1: i32, pub world0: u16, pub generation: u16 }
                    #[derive(Clone, Copy)] pub struct b2ChainId { pub index1: i32, pub world0: u16, pub generation: u16 }
                }
            "#,
        )
        .expect("production identity dependency source");
        let manifest = root.join("Cargo.toml");
        fs::write(
            &manifest,
            "[package]\nname = \"production-identity-fixture\"\nversion = \"0.0.0\"\nedition = \"2024\"\n\n[lib]\npath = \"lib.rs\"\n\n[dependencies]\nboxdd-sys = { path = \"native\" }\n",
        )
        .expect("production identity fixture manifest");
        let lib = root.join("lib.rs");
        fs::write(&lib, source).expect("production identity fixture source");
        let output = Command::new(env!("CARGO"))
            .args(["check", "--quiet", "--manifest-path"])
            .arg(&manifest)
            .env("CARGO_TARGET_DIR", root.join("target"))
            .output()
            .expect("production identity fixture cargo check");
        assert!(
            output.status.success(),
            "the production identity fixture must compile: {}",
            String::from_utf8_lossy(&output.stderr)
        );
        let syntax = syn::parse_file(source).expect("production identity fixture syntax");
        let coordinate = RustIndexCoordinate::source_single();
        let mut builder = IndexBuilder {
            crate_src: root.clone(),
            crate_name: "boxdd".to_owned(),
            coordinate,
            has_boxdd_sys_dependency: true,
            ..IndexBuilder::default()
        };
        let context = IndexModuleContext {
            modules: &[],
            modules_public: true,
            regular_module_dir: &root,
            path_attribute_dir: &root,
        };
        builder
            .collect_public_surface_file(&lib, &syntax, context, &mut BTreeSet::new())
            .expect("production identity fixture public surface");
        builder.resolve_public_surface("boxdd");
        builder
            .collect_file(&lib, &syntax, context)
            .expect("production identity fixture collection");
        let resolved_owners = builder
            .nodes
            .iter()
            .map(|node| {
                node.owner
                    .as_ref()
                    .filter(|owner| {
                        !type_ref_has_generic_root(owner, &node.generic_type_parameters)
                    })
                    .and_then(|owner| builder.resolve_type_ref(owner))
            })
            .collect::<Vec<_>>();
        let mut by_module_ident = BTreeMap::<(String, String), Vec<usize>>::new();
        let mut by_owner_ident = BTreeMap::<(String, String), Vec<usize>>::new();
        for (node_index, node) in builder.nodes.iter().enumerate() {
            by_module_ident
                .entry((node.module.clone(), node.ident.clone()))
                .or_default()
                .push(node_index);
            if let Some(owner) = &resolved_owners[node_index] {
                by_owner_ident
                    .entry((owner.clone(), node.ident.clone()))
                    .or_default()
                    .push(node_index);
            }
        }
        let resolver_contract =
            canonical_identity_registry_function_node(&builder, "resolve_body_for_brand")
                .is_some_and(|resolver| {
                    exact_production_event_resolver_body(
                        &builder,
                        resolver,
                        "try_body",
                        "raw",
                        "brand",
                        &resolved_owners,
                        &by_module_ident,
                        &by_owner_ident,
                    )
                });
        let clear_contract = by_owner_ident
            .get(&(
                "core::identity_registry::ActiveIdentityRegistry".to_owned(),
                "clear_retired_outputs".to_owned(),
            ))
            .is_some_and(|candidates| {
                matches!(candidates.as_slice(), [target] if exact_registry_clear_retired_outputs(
                    &builder,
                    *target,
                    &resolved_owners,
                    &by_module_ident,
                    &by_owner_ident,
                ))
            });
        let world_cleanup_contract = builder
            .canonical_public_paths
            .iter()
            .find_map(|(owner, public)| (public == "boxdd::World").then_some(owner))
            .is_some_and(|world_owner| {
                by_owner_ident
                    .get(&(world_owner.clone(), "clear_retired_identity_outputs".to_owned()))
                    .is_some_and(|candidates| {
                        matches!(candidates.as_slice(), [target] if exact_world_cleanup_to_identity_registry(
                            &builder,
                            *target,
                            world_owner,
                            "core::world_core::WorldCore",
                            &resolved_owners,
                            &by_module_ident,
                            &by_owner_ident,
                        ))
                    })
            });
        let proven = resolver_contract && clear_contract && world_cleanup_contract;
        fs::remove_dir_all(root).expect("production identity fixture cleanup");
        proven
    }

    #[test]
    fn production_identity_resolver_rejects_semantic_substitutions() {
        assert!(production_identity_resolver_is_proven(
            "production-identity-canonical",
            PRODUCTION_IDENTITY_RESOLVER_FIXTURE,
        ));

        let lookup_ignores_brand = PRODUCTION_IDENTITY_RESOLVER_FIXTURE.replace(
            "(registry.brand == brand).then_some(registry)",
            "Some(registry)",
        );
        assert!(!production_identity_resolver_is_proven(
            "production-identity-lookup-ignores-brand",
            &lookup_ignores_brand,
        ));

        let unchecked_raw = PRODUCTION_IDENTITY_RESOLVER_FIXTURE.replace(
            "if raw.index1 <= 0 { Err(ApiError::InvalidBodyId) } else if raw.world0 != self.world0 { Err(ApiError::WrongWorld) } else { Ok(()) }",
            "Ok(())",
        );
        assert!(!production_identity_resolver_is_proven(
            "production-identity-unchecked-raw",
            &unchecked_raw,
        ));

        let forged_nonce = PRODUCTION_IDENTITY_RESOLVER_FIXTURE.replace(
            "BodyId { index1: raw.index1, generation: raw.generation, brand: self, registration_nonce }",
            "BodyId { index1: raw.index1, generation: raw.generation, brand: self, registration_nonce: RegistrationNonce::new(1).ok().unwrap() }",
        );
        assert!(!production_identity_resolver_is_proven(
            "production-identity-forged-nonce",
            &forged_nonce,
        ));

        let wrong_key_equivalence = PRODUCTION_IDENTITY_RESOLVER_FIXTURE
            .replace("#[derive(PartialEq, Eq, Hash)]\n                pub struct RawKey", "pub struct RawKey")
            .replace(
                "                impl RawKey {",
                "                impl PartialEq for RawKey {\n                    fn eq(&self, other: &Self) -> bool { self.index1 == other.index1 }\n                }\n                impl Eq for RawKey {}\n                impl std::hash::Hash for RawKey {\n                    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {\n                        std::hash::Hasher::write_i32(state, self.index1);\n                    }\n                }\n\n                impl RawKey {",
            );
        assert!(!production_identity_resolver_is_proven(
            "production-identity-wrong-key-equivalence",
            &wrong_key_equivalence,
        ));

        let retained_outputs = PRODUCTION_IDENTITY_RESOLVER_FIXTURE.replace(
            "state.retired_chains.clear();",
            "state.retired_chains.len();",
        );
        assert!(!production_identity_resolver_is_proven(
            "production-identity-retained-outputs",
            &retained_outputs,
        ));

        let shadowed_registry_clear = PRODUCTION_IDENTITY_RESOLVER_FIXTURE
            .replace(
                "        mod error {",
                "        trait RegistryClearShadow {\n            fn clear_retired_outputs(&self);\n        }\n\n        impl RegistryClearShadow for std::sync::Arc<core::identity_registry::ActiveIdentityRegistry> {\n            fn clear_retired_outputs(&self) {}\n        }\n\n        mod error {",
            )
            .replace(
                "ActiveIdentityRegistry::clear_retired_outputs(&self.identities);",
                "self.identities.clear_retired_outputs();",
            );
        assert!(!production_identity_resolver_is_proven(
            "production-identity-shadowed-registry-clear",
            &shadowed_registry_clear,
        ));
    }

    const PRODUCTION_WORLD_ACCESS_FIXTURE: &str = r#"
        use std::rc::Rc;

        mod error {
            pub enum ApiError { ObjectIdentityExhausted }
            pub type ApiResult<T> = Result<T, ApiError>;
        }

        mod id {
            use crate::error::{ApiError, ApiResult};

            #[derive(Copy, Clone, Default, PartialEq, Eq)]
            pub struct IdBrand(pub u64);

            #[derive(Copy, Clone, Default, PartialEq, Eq)]
            pub struct ContactEpoch(u64);

            impl ContactEpoch {
                pub fn checked_next(self) -> ApiResult<Self> {
                    self.0.checked_add(1).map(Self).ok_or(ApiError::ObjectIdentityExhausted)
                }
            }
        }

        mod events {
            pub struct EventCache;
        }

        mod core {
            pub mod world_core {
                use std::cell::Cell;

                use crate::error::{ApiError, ApiResult};
                use crate::id::{ContactEpoch, IdBrand};

                #[derive(Copy, Clone, PartialEq, Eq)]
                pub enum LifecycleState {
                    Live,
                    Poisoned,
                }

                pub struct WorldCore {
                    pub(crate) id: u32,
                    pub(crate) brand: IdBrand,
                    lifecycle: Cell<LifecycleState>,
                    contact_epoch: Cell<ContactEpoch>,
                }

                impl WorldCore {
                    pub fn brand(&self) -> IdBrand { self.brand }

                    pub fn advance_contact_epoch(&self) -> ApiResult<ContactEpoch> {
                        let next = match self.contact_epoch.get().checked_next() {
                            Ok(next) => next,
                            Err(error) => {
                                WorldCore::poison(self);
                                return Err(error);
                            }
                        };
                        self.contact_epoch.set(next);
                        Ok(next)
                    }

                    fn poison(&self) {
                        if std::cell::Cell::get(&self.lifecycle) == LifecycleState::Live {
                            std::cell::Cell::set(&self.lifecycle, LifecycleState::Poisoned);
                        }
                    }
                }
            }
        }

        pub struct World {
            core: Rc<core::world_core::WorldCore>,
            events: Rc<events::EventCache>,
        }

        impl World {
            pub fn core(&self) -> &core::world_core::WorldCore { &self.core }
            pub fn raw(&self) -> u32 { self.core.id }
            pub fn brand(&self) -> id::IdBrand { core::world_core::WorldCore::brand(&self.core) }
            pub fn event_cache(&self) -> &events::EventCache { &self.events }

            pub fn advance_epoch(&self) -> error::ApiResult<id::ContactEpoch> {
                let epoch = core::world_core::WorldCore::advance_contact_epoch(&self.core)?;
                Ok(epoch)
            }
        }
    "#;

