    fn write_event_protocol_local_dependency(root: &Path) {
        let dependency_root = root.join("native");
        fs::create_dir_all(&dependency_root).expect("event protocol dependency root");
        fs::write(
            dependency_root.join("Cargo.toml"),
            "[package]\nname = \"boxdd-sys\"\nversion = \"0.0.0\"\nedition = \"2024\"\n\n[lib]\npath = \"lib.rs\"\n",
        )
        .expect("event protocol dependency manifest");
        fs::write(
            dependency_root.join("lib.rs"),
            r#"
                pub mod ffi {
                    #[derive(Clone, Copy, Default)]
                    pub struct b2WorldId;
                    #[derive(Clone, Copy, Default)]
                    pub struct b2BodyId;
                    #[derive(Clone, Copy, Default)]
                    pub struct b2ShapeId;
                    #[derive(Clone, Copy, Default)]
                    pub struct b2JointId;
                    #[derive(Clone, Copy, Default)]
                    pub struct b2Vec2 { pub x: f32, pub y: f32 }
                    #[derive(Clone, Copy, Default)]
                    pub struct b2ContactId {
                        pub index1: i32,
                        pub world0: u16,
                        pub generation: u32,
                    }
                    #[derive(Clone, Copy, Default)]
                    pub struct b2BodyMoveEvent { pub bodyId: b2BodyId, pub fellAsleep: bool }
                    #[derive(Clone, Copy, Default)]
                    pub struct b2ContactBeginTouchEvent {
                        pub shapeIdA: b2ShapeId,
                        pub shapeIdB: b2ShapeId,
                        pub contactId: b2ContactId,
                    }
                    #[derive(Clone, Copy, Default)]
                    pub struct b2ContactEndTouchEvent {
                        pub shapeIdA: b2ShapeId,
                        pub shapeIdB: b2ShapeId,
                        pub contactId: b2ContactId,
                    }
                    #[derive(Clone, Copy, Default)]
                    pub struct b2ContactHitEvent {
                        pub shapeIdA: b2ShapeId,
                        pub shapeIdB: b2ShapeId,
                        pub contactId: b2ContactId,
                        pub normal: b2Vec2,
                        pub approachSpeed: f32,
                    }
                    #[derive(Clone, Copy, Default)]
                    pub struct b2JointEvent { pub jointId: b2JointId }
                    #[derive(Clone, Copy, Default)]
                    pub struct b2SensorBeginTouchEvent {
                        pub sensorShapeId: b2ShapeId,
                        pub visitorShapeId: b2ShapeId,
                    }
                    #[derive(Clone, Copy, Default)]
                    pub struct b2SensorEndTouchEvent {
                        pub sensorShapeId: b2ShapeId,
                        pub visitorShapeId: b2ShapeId,
                    }
                    #[derive(Clone, Copy)]
                    pub struct b2BodyEvents {
                        pub moveEvents: *const b2BodyMoveEvent,
                        pub moveCount: i32,
                    }
                    impl Default for b2BodyEvents {
                        fn default() -> Self { Self { moveEvents: core::ptr::null(), moveCount: 0 } }
                    }
                    #[derive(Clone, Copy)]
                    pub struct b2ContactEvents {
                        pub beginEvents: *const b2ContactBeginTouchEvent,
                        pub beginCount: i32,
                        pub endEvents: *const b2ContactEndTouchEvent,
                        pub endCount: i32,
                        pub hitEvents: *const b2ContactHitEvent,
                        pub hitCount: i32,
                    }
                    impl Default for b2ContactEvents {
                        fn default() -> Self {
                            Self {
                                beginEvents: core::ptr::null(), beginCount: 0,
                                endEvents: core::ptr::null(), endCount: 0,
                                hitEvents: core::ptr::null(), hitCount: 0,
                            }
                        }
                    }
                    #[derive(Clone, Copy)]
                    pub struct b2JointEvents { pub jointEvents: *const b2JointEvent, pub count: i32 }
                    impl Default for b2JointEvents {
                        fn default() -> Self { Self { jointEvents: core::ptr::null(), count: 0 } }
                    }
                    #[derive(Clone, Copy)]
                    pub struct b2SensorEvents {
                        pub beginEvents: *const b2SensorBeginTouchEvent,
                        pub beginCount: i32,
                        pub endEvents: *const b2SensorEndTouchEvent,
                        pub endCount: i32,
                    }
                    impl Default for b2SensorEvents {
                        fn default() -> Self {
                            Self {
                                beginEvents: core::ptr::null(), beginCount: 0,
                                endEvents: core::ptr::null(), endCount: 0,
                            }
                        }
                    }
                    #[allow(non_snake_case)]
                    pub unsafe fn b2World_GetBodyEvents(_: b2WorldId) -> b2BodyEvents { b2BodyEvents::default() }
                    #[allow(non_snake_case)]
                    pub unsafe fn b2World_GetContactEvents(_: b2WorldId) -> b2ContactEvents { b2ContactEvents::default() }
                    #[allow(non_snake_case)]
                    pub unsafe fn b2World_GetJointEvents(_: b2WorldId) -> b2JointEvents { b2JointEvents::default() }
                    #[allow(non_snake_case)]
                    pub unsafe fn b2World_GetSensorEvents(_: b2WorldId) -> b2SensorEvents { b2SensorEvents::default() }
                    #[allow(non_snake_case)]
                    pub unsafe fn b2World_Step(_: b2WorldId, _: f32, _: i32) {}
                }
            "#,
        )
        .expect("event protocol dependency source");
    }

