    #[test]
    fn path_attribute_relocation_keeps_rustc_physical_child_resolution() {
        let root = fixture_root("path-attribute-rustc-child-resolution");
        fs::create_dir_all(root.join("custom/inline")).expect("custom fixture root");
        fs::create_dir_all(root.join("custom/outer")).expect("wrong virtual fixture root");
        fs::create_dir_all(root.join("custom/inline/outer")).expect("wrong nested fixture root");
        fs::write(
            root.join("Cargo.toml"),
            "[package]\nname = \"rust-index-fixture\"\nversion = \"0.0.0\"\nedition = \"2024\"\n\n[dependencies]\nboxdd-sys = \"0\"\n",
        )
        .expect("fixture manifest");
        fs::write(
            root.join("custom/weird.rs"),
            r#"
                pub mod child;
                pub mod inline {
                    #[path = "child.rs"]
                    pub mod child;
                    pub use child::safe_api;
                }
                pub use child::safe_api as direct_safe_api;
            "#,
        )
        .expect("relocated module");
        fs::write(
            root.join("custom/child.rs"),
            "pub fn safe_api() { unsafe { boxdd_sys::ffi::b2World_Step() }; }\n",
        )
        .expect("physical direct child module");
        fs::write(
            root.join("custom/outer/child.rs"),
            "pub fn safe_api() { unsafe { boxdd_sys::ffi::b2Body_SetAwake() }; }\n",
        )
        .expect("wrong virtual direct child candidate");
        fs::write(
            root.join("custom/inline/child.rs"),
            "pub fn safe_api() { unsafe { boxdd_sys::ffi::b2World_Step() }; }\n",
        )
        .expect("physical inline child module");
        fs::write(
            root.join("custom/inline/outer/child.rs"),
            "pub fn safe_api() { unsafe { boxdd_sys::ffi::b2Body_SetAwake() }; }\n",
        )
        .expect("wrong nested virtual child candidate");
        let lib = root.join("lib.rs");
        fs::write(&lib, "#[path = \"custom/weird.rs\"]\npub mod outer;\n").expect("fixture source");

        let index = index_crate(&lib, "fixture").expect("relocated module should index");
        assert!(index.path_reaches_symbol("fixture::outer::direct_safe_api", "b2World_Step"));
        assert!(!index.path_reaches_symbol("fixture::outer::direct_safe_api", "b2Body_SetAwake"));
        assert!(index.path_reaches_symbol("fixture::outer::inline::safe_api", "b2World_Step"));
        assert!(!index.path_reaches_symbol("fixture::outer::inline::safe_api", "b2Body_SetAwake"));
        fs::remove_dir_all(root).expect("fixture cleanup");
    }

