    #[test]
    fn nested_cfg_cannot_pollute_calls_or_abi_witnesses() {
        let index = checked_index_fixture(
            "nested-body-cfg",
            r#"
                pub fn disabled_call() {
                    #[cfg(any())]
                    unsafe { boxdd_sys::ffi::b2World_Step() };
                }

                pub fn disabled_cfg_attr_call() {
                    #[cfg_attr(all(), cfg(any()))]
                    unsafe { boxdd_sys::ffi::b2World_Step() };
                }

                pub fn disabled_type() {
                    #[cfg(any())]
                    let _: boxdd_sys::ffi::b2DisabledType = unsafe {
                        core::mem::zeroed()
                    };
                }

                struct Guard;
                impl Drop for Guard {
                    fn drop(&mut self) {
                        unsafe { boxdd_sys::ffi::b2World_Step() };
                    }
                }
                pub struct DisabledOwner {
                    #[cfg(any())]
                    guard: Guard,
                }

                pub fn disabled_struct_field() {
                    struct Holder {
                        #[cfg(any())]
                        value: (),
                    }
                    let _ = Holder {
                        #[cfg(any())]
                        value: unsafe { boxdd_sys::ffi::b2World_Step() },
                    };
                }

                pub fn disabled_match_arm() {
                    match () {
                        #[cfg(any())]
                        _ => unsafe { boxdd_sys::ffi::b2World_Step() },
                        _ => (),
                    }
                }
            "#,
        );

        for path in [
            "fixture::disabled_call",
            "fixture::disabled_cfg_attr_call",
            "fixture::DisabledOwner",
            "fixture::disabled_struct_field",
            "fixture::disabled_match_arm",
        ] {
            assert!(!index.path_reaches_symbol(path, "b2World_Step"), "{path}");
        }
        assert!(
            !index.path_has_ffi_type_witness(
                "fixture::disabled_type",
                "boxdd_sys::ffi::b2DisabledType"
            )
        );

        let evidence = checked_evidence_fixture(
            "nested-evidence-cfg",
            "pub fn tick() {}",
            r#"
                #[test]
                fn proof() {
                    struct Holder {
                        #[cfg(any())]
                        value: (),
                    }
                    #[cfg(any())]
                    boxdd::tick();
                    #[cfg_attr(all(), cfg(any()))]
                    boxdd::tick();
                    let _ = Holder {
                        #[cfg(any())]
                        value: boxdd::tick(),
                    };
                }
            "#,
            "proof",
        );
        assert!(evidence.called_public_paths.is_empty());
    }

    #[test]
    fn attribute_macros_cannot_publish_unexpanded_source_evidence() {
        let root = fixture_root("attribute-macro-source");
        write_local_dependency(&root, "native", "boxdd-sys");
        fs::create_dir_all(root.join("erase/src")).expect("proc macro source");
        fs::write(
            root.join("erase/Cargo.toml"),
            "[package]\nname = \"erase\"\nversion = \"0.0.0\"\nedition = \"2024\"\n\n[lib]\nproc-macro = true\n",
        )
        .expect("proc macro manifest");
        fs::write(
            root.join("erase/src/lib.rs"),
            r#"
                extern crate proc_macro;
                use proc_macro::TokenStream;

                #[proc_macro_attribute]
                pub fn erase(_: TokenStream, _: TokenStream) -> TokenStream {
                    "fn local_helper() {}".parse().expect("fixed expansion")
                }
            "#,
        )
        .expect("proc macro implementation");
        fs::create_dir_all(root.join("boxdd/src")).expect("fixture library");
        fs::create_dir_all(root.join("boxdd/tests")).expect("fixture tests");
        let manifest = root.join("boxdd/Cargo.toml");
        fs::write(
            &manifest,
            "[package]\nname = \"boxdd\"\nversion = \"0.0.0\"\nedition = \"2024\"\n\n[dependencies]\nboxdd-sys = { path = \"../native\" }\nerase = { path = \"../erase\" }\n",
        )
        .expect("fixture manifest");
        fs::write(
            root.join("boxdd/src/lib.rs"),
            r#"
                #[erase::erase]
                pub fn fake() {
                    unsafe { boxdd_sys::ffi::b2World_Step() };
                }

                pub fn tick() {}
            "#,
        )
        .expect("fixture library source");
        fs::write(
            root.join("boxdd/tests/proof.rs"),
            r#"
                #[erase::erase]
                fn local_helper() { boxdd::tick(); }

                #[test]
                fn proof() { local_helper(); }
            "#,
        )
        .expect("fixture evidence source");
        let output = Command::new(env!("CARGO"))
            .args(["check", "--quiet", "--tests", "--manifest-path"])
            .arg(&manifest)
            .env("CARGO_TARGET_DIR", root.join("target"))
            .output()
            .expect("fixture cargo check");
        assert!(
            output.status.success(),
            "the attribute-macro attack must compile: {}",
            String::from_utf8_lossy(&output.stderr)
        );

        let index = index_boxdd(&root).expect("fixture Rust index");
        assert!(!index.contains_public_path("boxdd::fake"));
        assert!(index.paths_for_symbol("b2World_Step").next().is_none());
        let evidence = index_test_evidence(&root, "boxdd/tests/proof.rs", "proof", &index)
            .expect("fixture evidence index");
        assert!(evidence.called_public_paths.is_empty());
        fs::remove_dir_all(root).expect("fixture cleanup");
    }

