    #[test]
    fn imported_rc_and_arc_fields_preserve_private_drop_coverage() {
        let index = checked_index_fixture(
            "imported-owned-wrapper-raii",
            r#"
                use std::rc::Rc;
                use std::sync::Arc;

                mod internals {
                    pub(crate) struct WorldCore;
                    impl WorldCore {
                        pub(crate) fn shutdown_native(&self) {
                            self.finish_native_shutdown();
                        }
                        fn finish_native_shutdown(&self) {
                            unsafe { boxdd_sys::ffi::b2World_Step() };
                        }
                    }
                    impl Drop for WorldCore {
                        fn drop(&mut self) {
                            self.shutdown_native();
                        }
                    }

                    pub(crate) struct SharedCore;
                    impl Drop for SharedCore {
                        fn drop(&mut self) {
                            unsafe { boxdd_sys::ffi::b2World_Step() };
                        }
                    }
                }

                use internals::{SharedCore, WorldCore};

                pub struct World {
                    core: Rc<WorldCore>,
                }
                impl Drop for World {
                    fn drop(&mut self) {
                        self.core.shutdown_native();
                    }
                }

                pub struct SharedWorld {
                    core: Arc<SharedCore>,
                }

                mod local {
                    pub struct Rc<T>(pub T);
                    pub struct Arc<T>(pub T);
                }
                mod shadowed {
                    use super::local::{Arc, Rc};

                    struct Guard;
                    impl Drop for Guard {
                        fn drop(&mut self) {
                            unsafe { boxdd_sys::ffi::b2World_Step() };
                        }
                    }

                    pub struct RcOwner(Rc<Guard>);
                    pub struct ArcOwner(Arc<Guard>);
                }
                pub use shadowed::{ArcOwner as LocalArcOwner, RcOwner as LocalRcOwner};
            "#,
        );

        assert!(index.path_reaches_symbol("fixture::World", "b2World_Step"));
        assert!(index.path_reaches_symbol("fixture::SharedWorld", "b2World_Step"));
        assert!(!index.path_reaches_symbol("fixture::LocalRcOwner", "b2World_Step"));
        assert!(!index.path_reaches_symbol("fixture::LocalArcOwner", "b2World_Step"));
    }

    #[test]
    fn standard_option_fields_preserve_nested_drop_coverage() {
        let index = checked_index_fixture(
            "standard-option-raii",
            r#"
                struct NativeRecording;
                impl NativeRecording {
                    fn finish_native(&self) {
                        unsafe { boxdd_sys::ffi::b2World_Step() };
                    }
                }
                impl Drop for NativeRecording {
                    fn drop(&mut self) {
                        self.finish_native();
                    }
                }
                pub struct RecordingSession {
                    native: Option<NativeRecording>,
                }

                use std::option::Option as StdOption;
                struct ImportedNative;
                impl Drop for ImportedNative {
                    fn drop(&mut self) {
                        unsafe { boxdd_sys::ffi::b2World_Step() };
                    }
                }
                pub struct ImportedOptionOwner(StdOption<ImportedNative>);

                mod local {
                    pub struct Option<T>(pub T);
                }
                mod attacks {
                    use super::local::Option;
                    use core::ptr::NonNull;

                    struct Guard;
                    impl Drop for Guard {
                        fn drop(&mut self) {
                            unsafe { boxdd_sys::ffi::b2World_Step() };
                        }
                    }

                    struct DropWrapper<T>(T);
                    impl<T> Drop for DropWrapper<T> {
                        fn drop(&mut self) {}
                    }

                    pub struct LocalOptionOwner(Option<Guard>);
                    pub struct BorrowedOptionOwner(std::option::Option<&'static Guard>);
                    pub struct PointerOptionOwner(std::option::Option<NonNull<Guard>>);
                    pub struct CustomDropOptionOwner(
                        std::option::Option<DropWrapper<Guard>>,
                    );
                }
                pub use attacks::{
                    BorrowedOptionOwner,
                    CustomDropOptionOwner,
                    LocalOptionOwner,
                    PointerOptionOwner,
                };

                mod shadowed {
                    mod std {
                        pub mod option {
                            pub struct Option<T>(pub T);
                        }
                    }

                    struct Guard;
                    impl Drop for Guard {
                        fn drop(&mut self) {
                            unsafe { boxdd_sys::ffi::b2World_Step() };
                        }
                    }

                    pub struct Owner(std::option::Option<Guard>);
                }
                pub use shadowed::Owner as ShadowedOptionOwner;
            "#,
        );

        for path in ["fixture::RecordingSession", "fixture::ImportedOptionOwner"] {
            assert!(
                index.path_reaches_symbol(path, "b2World_Step"),
                "`{path}` must inherit its standard Option payload's Drop path"
            );
        }
        for path in [
            "fixture::LocalOptionOwner",
            "fixture::BorrowedOptionOwner",
            "fixture::PointerOptionOwner",
            "fixture::CustomDropOptionOwner",
            "fixture::ShadowedOptionOwner",
        ] {
            assert!(
                !index.path_reaches_symbol(path, "b2World_Step"),
                "`{path}` must not forge Option ownership"
            );
        }
    }

