    #[test]
    fn runtime_evidence_stops_at_macros_and_non_linear_control_flow() {
        let library = r#"
            pub fn tick() -> bool { true }
            pub fn pointer() -> *mut i32 { core::ptr::null_mut() }
        "#;
        let source = r#"
            fn consume<A, B>(_: A, _: B) {}
            struct Pair<A, B> { first: A, second: B }

            #[test]
            fn macro_argument() { assert!(boxdd::tick()); }

            #[test]
            fn qualified_macro_argument() { std::assert!(boxdd::tick()); }

            #[test]
            fn macro_before_call() {
                println!();
                boxdd::tick();
            }

            #[test]
            fn let_else_before_call() {
                let Some(_) = None::<()> else { return; };
                boxdd::tick();
            }

            #[test]
            fn loop_before_call() {
                loop {}
                boxdd::tick();
            }

            #[test]
            fn while_true_before_call() {
                while true {}
                boxdd::tick();
            }

            #[test]
            fn first_call_argument_exits() {
                consume(return, boxdd::tick());
            }

            #[test]
            fn first_tuple_element_exits() {
                let _ = (return, boxdd::tick());
            }

            #[test]
            fn first_array_element_exits() {
                let _ = [return, boxdd::tick()];
            }

            #[test]
            fn first_struct_field_exits() {
                let _ = Pair { first: return, second: boxdd::tick() };
            }

            #[test]
            fn left_binary_operand_exits() {
                let _ = { return; false } == boxdd::tick();
            }

            #[test]
            fn assignment_rhs_exits_before_lhs() {
                unsafe { *boxdd::pointer() = { return; }; }
            }

            #[test]
            fn compound_assignment_rhs_exits_before_lhs() {
                unsafe { *boxdd::pointer() += { return; 1 }; }
            }

            #[test]
            fn statically_empty_loop_allows_following_call() {
                while false {}
                boxdd::tick();
            }
        "#;

        for item in [
            "macro_argument",
            "qualified_macro_argument",
            "macro_before_call",
            "let_else_before_call",
            "loop_before_call",
            "while_true_before_call",
            "first_call_argument_exits",
            "first_tuple_element_exits",
            "first_array_element_exits",
            "first_struct_field_exits",
            "left_binary_operand_exits",
            "assignment_rhs_exits_before_lhs",
            "compound_assignment_rhs_exits_before_lhs",
        ] {
            let evidence = evidence_fixture(&format!("flow-{item}"), library, source, item);
            assert!(
                evidence.called_public_paths.is_empty(),
                "`{item}` must fail closed"
            );
        }
        let positive = evidence_fixture(
            "flow-statically-empty-loop",
            library,
            source,
            "statically_empty_loop_allows_following_call",
        );
        assert_eq!(
            positive.called_public_paths,
            BTreeSet::from(["boxdd::tick".to_owned()])
        );
    }

    #[test]
    fn constant_integer_comparisons_ignore_literal_suffix_spelling() {
        let one = syn::parse_str::<Expr>("1").expect("integer expression");
        let one_u32 = syn::parse_str::<Expr>("1u32").expect("suffixed integer expression");
        let equal = syn::parse_str::<Expr>("1 == 1u32").expect("equality expression");
        let different = syn::parse_str::<Expr>("1 != 1u32").expect("inequality expression");
        assert_eq!(constant_scalar(&one), constant_scalar(&one_u32));
        assert_eq!(constant_bool(&equal), Some(true));
        assert_eq!(constant_bool(&different), Some(false));
    }

    #[test]
    fn explicit_drop_requires_a_proven_unwrapped_owned_value() {
        let library = r#"
            struct Guard;
            impl Drop for Guard { fn drop(&mut self) {} }

            pub struct Handle { guard: Guard }
            impl Handle {
                pub fn new() -> Self { Self { guard: Guard } }
                pub fn borrow(&self) -> &Self { self }
                pub fn borrow_mut(&mut self) -> &mut Self { self }
                pub fn boxed() -> Box<Self> { Box::new(Self::new()) }
            }
        "#;
        let source = r#"
            use boxdd::Handle;

            trait FakeClone { fn clone(&self) -> Handle; }
            impl FakeClone for Handle {
                fn clone(&self) -> Handle { boxdd::Handle::new() }
            }

            trait BoxDestroy { fn destroy(self); }
            impl BoxDestroy for Box<Handle> { fn destroy(self) {} }

            #[test]
            fn owned() {
                let handle = boxdd::Handle::new();
                core::mem::drop(handle);
            }

            #[test]
            fn shared_reference() {
                let handle = boxdd::Handle::new();
                core::mem::drop(&handle);
            }

            #[test]
            fn mutable_reference() {
                let mut handle = boxdd::Handle::new();
                core::mem::drop(&mut handle);
            }

            #[test]
            fn borrowed_return() {
                let handle = boxdd::Handle::new();
                core::mem::drop(boxdd::Handle::borrow(&handle));
            }

            #[test]
            fn bound_borrowed_return() {
                let handle = boxdd::Handle::new();
                let borrowed = boxdd::Handle::borrow(&handle);
                core::mem::drop(borrowed);
            }

            #[test]
            fn boxed_return() { core::mem::drop(boxdd::Handle::boxed()); }

            #[test]
            fn trait_clone_result() {
                let handle = boxdd::Handle::new();
                core::mem::drop(handle.clone());
            }

            #[test]
            fn boxed_trait_method() {
                let handle = Box::new(boxdd::Handle::new());
                handle.destroy();
            }
        "#;

        let owned = evidence_fixture("drop-owned", library, source, "owned");
        assert_eq!(
            owned.dropped_public_types,
            BTreeSet::from(["boxdd::Handle".to_owned()])
        );
        for item in [
            "shared_reference",
            "mutable_reference",
            "borrowed_return",
            "bound_borrowed_return",
            "boxed_return",
            "trait_clone_result",
            "boxed_trait_method",
        ] {
            let evidence = evidence_fixture(&format!("drop-{item}"), library, source, item);
            assert!(
                evidence.dropped_public_types.is_empty(),
                "`{item}` must not prove ownership"
            );
        }
    }

    #[test]
    fn generic_and_async_calls_cannot_forge_runtime_evidence() {
        let evidence = checked_evidence_fixture(
            "generic-and-async-evidence",
            r#"
                struct Guard;
                impl Drop for Guard { fn drop(&mut self) {} }

                pub struct T(Guard);
                pub fn generic<T: Default>() -> T { T::default() }

                #[derive(Debug)]
                pub struct Handle;
                pub fn result() -> Result<(), Handle> { Ok(()) }

                pub fn tick() {}
                pub async fn async_tick() {}
            "#,
            r#"
                use boxdd::Handle;
                use boxdd as Api;

                fn generic_drop<Handle>(value: Handle) {
                    core::mem::drop(value);
                }

                trait LocalApi { fn tick(); }
                impl LocalApi for () { fn tick() {} }
                fn generic_call<Api: LocalApi>() { Api::tick(); }

                #[test]
                fn proof() {
                    core::mem::drop(boxdd::generic::<()>());
                    core::mem::drop(boxdd::result().unwrap());
                    generic_drop(());
                    generic_call::<()>();
                    let _future = boxdd::async_tick();
                }
            "#,
            "proof",
        );

        assert_eq!(
            evidence.called_public_paths,
            BTreeSet::from(["boxdd::generic".to_owned(), "boxdd::result".to_owned()]),
            "generic dispatch and an unpolled future must not become public calls"
        );
        assert!(
            evidence.dropped_public_types.is_empty(),
            "unexpected drops: {:?}",
            evidence.dropped_public_types
        );
    }

