    #[test]
    fn replay_view_closure_calls_are_runtime_evidence() {
        let root = fixture_root("replay-view-evidence");
        fs::create_dir_all(root.join("boxdd/src")).expect("fixture source");
        fs::create_dir_all(root.join("boxdd/tests")).expect("fixture tests");
        fs::write(
            root.join("boxdd/Cargo.toml"),
            "[package]\nname = \"boxdd\"\nversion = \"0.0.0\"\nedition = \"2024\"\n\n[dependencies]\nboxdd-sys = \"0\"\n",
        )
        .expect("fixture manifest");
        fs::write(
            root.join("boxdd/src/lib.rs"),
            r#"
                pub struct ReplayPlayer;
                pub struct ReplayView;
                pub struct ReplayQueryView;
                pub struct Other;

                impl ReplayPlayer {
                    pub fn new() -> Self { Self }
                    pub fn with_view<T>(&self, callback: impl FnOnce(&ReplayView) -> T) -> Result<T, ()> {
                        unsafe { boxdd_sys::ffi::b2RecPlayer_GetBodyCount() };
                        Ok(callback(&ReplayView))
                    }
                }
                impl ReplayView {
                    pub fn body_count(&self) -> usize {
                        unsafe { boxdd_sys::ffi::b2RecPlayer_GetBodyCount() };
                        0
                    }
                    pub fn query(&self) -> ReplayQueryView {
                        unsafe { boxdd_sys::ffi::b2RecPlayer_GetFrameQuery() };
                        ReplayQueryView
                    }
                }
                impl ReplayQueryView {
                    pub fn hit(&self) {
                        unsafe { boxdd_sys::ffi::b2RecPlayer_GetFrameQueryHit() };
                    }
                }
                impl Other {
                    pub fn body_count(&self) {
                        unsafe { boxdd_sys::ffi::b2WrongClosureOwner() };
                    }
                }
            "#,
        )
        .expect("fixture library");
        fs::write(
            root.join("boxdd/tests/replay.rs"),
            r#"
                use boxdd::{Other, ReplayPlayer};

                #[test]
                fn replay_view_calls() {
                    let player = ReplayPlayer::new();
                    let view = Other;
                    boxdd::ReplayPlayer::with_view(&player, |view| {
                        let _ = boxdd::ReplayView::body_count(view);
                        boxdd::ReplayQueryView::hit(&boxdd::ReplayView::query(view));
                    }).unwrap();
                    let _ = view;
                }
            "#,
        )
        .expect("fixture evidence");

        let rust_index = index_boxdd(&root).expect("fixture Rust index");
        let evidence = index_test_evidence(
            &root,
            "boxdd/tests/replay.rs",
            "replay_view_calls",
            &rust_index,
        )
        .expect("replay view evidence index");
        assert!(
            evidence
                .called_public_paths
                .contains("boxdd::ReplayPlayer::with_view")
        );
        assert!(
            evidence
                .called_public_paths
                .contains("boxdd::ReplayView::body_count")
        );
        assert!(
            evidence
                .called_public_paths
                .contains("boxdd::ReplayView::query")
        );
        assert!(
            evidence
                .called_public_paths
                .contains("boxdd::ReplayQueryView::hit")
        );
        assert!(
            !evidence
                .called_public_paths
                .contains("boxdd::Other::body_count")
        );
        fs::remove_dir_all(root).expect("fixture cleanup");
    }

